head.script:
scwin.onpageload = function () {
    // 사용자 인증 정보 확인 (메인페이지에서 전달받은 정보 사용)
    let userId = scwin.getCurrentUserId();
    scwin.projectId = $p.parent().dm_projectVo.get("projectId");
};

// WebSocket 전역 변수
scwin.websocket = null;
scwin.isWebSocketConnected = false;
scwin.reconnectAttempts = 0;
scwin.maxReconnectAttempts = 5;
scwin.reconnectDelay = 3000; // 3초
scwin.wsUrls = null; // WebSocket URL 목록 저장

// 태스크 데이터 전역 변수
scwin.taskList = null; // 서버에서 받아온 태스크 목록

// 드래그 락 시스템 전역 변수
scwin.lockedCards = new Map(); // taskId -> {userId, userName, timestamp}
scwin.myLockedCards = new Set(); // 내가 락한 카드들의 taskId
scwin.lockTimeout = 30000; // 30초 후 자동 락 해제

// 중복 메시지 처리 방지 시스템
scwin.processedMessages = new Set(); // 처리된 메시지 ID 추적

/**
 * WebSocket 연결 초기화
 */
scwin.initWebSocket = function () {

    // 디바운싱 타이머 변수
    scwin.debounceTimer = null;
    scwin.debounceDelay = 2000;

    // 간단한 WebSocket URL
    let protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    let host = window.location.host;

    // 단일 칸반 웹소켓 경로 (중복 세션 방지)
    let websocketUrl = protocol + '//' + host + '/InsWebApp/kanban';

    try {
        scwin.websocket = new WebSocket(websocketUrl);
        // 핸들러 설정
        scwin.setupWebSocketHandlers(websocketUrl);
    } catch (error) {
        scwin.websocket = null;
        scwin.isWebSocketConnected = false;
    }
};

/**
 * WebSocket 핸들러 설정 (재사용 가능한 함수)
 */
scwin.setupWebSocketHandlers = function (websocketUrl) {
    scwin.websocket.onopen = function (event) {
        scwin.isWebSocketConnected = true;
        scwin.sendUserJoinMessage();
    };

    scwin.websocket.onmessage = function (event) {
        try {
            let message = JSON.parse(event.data);
            scwin.handleWebSocketMessage(message);
        } catch (error) {
        }
    };

    scwin.websocket.onclose = function (event) {
        scwin.isWebSocketConnected = false;
        scwin.websocket = null;
    };

    scwin.websocket.onerror = function (event) {        
        scwin.isWebSocketConnected = false;
    };
};

/**
 * WebSocket 연결 성공 이벤트
 */
scwin.onWebSocketOpen = function (event) {
    scwin.isWebSocketConnected = true;
    scwin.reconnectAttempts = 0;

    // 사용자 참여 메시지 전송
    scwin.sendUserJoinMessage();

    // 연결 상태 표시 (선택사항)
    scwin.updateConnectionStatus(true);
};

/**
 * WebSocket 메시지 수신 이벤트
 */
scwin.onWebSocketMessage = function (event) {
    try {
        let message = JSON.parse(event.data);
        scwin.handleWebSocketMessage(message);
    } catch (error) {
    }
};

/**
 * WebSocket 연결 종료 이벤트
 */
scwin.onWebSocketClose = function (event) {
    scwin.isWebSocketConnected = false;

    // 연결 상태 표시 업데이트
    scwin.updateConnectionStatus(false);

};

/**
 * 사용자 참여 메시지 전송
 */
scwin.sendUserJoinMessage = function () {
    let currentUserId = $p.parent().dm_userInfo.get("userId");
    let projectId = scwin.currentProjectData.projectId;

    let message = {
        type: "USER_JOIN",
        userId: currentUserId,
        projectId: projectId, // 프로젝트 ID 추가 (기본값: 1)
        timestamp: Date.now()
    };    
    scwin.sendWebSocketMessage(message);
};

/**
 * WebSocket 메시지 전송
 */
scwin.sendWebSocketMessage = function (message) {
    if (scwin.websocket && scwin.websocket.readyState === WebSocket.OPEN) {
        let jsonMessage = JSON.stringify(message);
        scwin.websocket.send(jsonMessage);
    } else {
    }
};

/**
 * WebSocket 메시지 처리
 */
scwin.handleWebSocketMessage = function (message) {
    switch (message.type) {
        case "CONNECTION_SUCCESS":
            break;
        case "USER_JOIN_SUCCESS":
            break;
        case "CARD_MOVED":
        case "CARD_MOVE":
            scwin.handleCardMovedMessage(message);
            break;
        case "CARD_LOCK":
            scwin.handleCardLockMessage(message);
            break;
        case "TASK_UPDATED":
            scwin.handleTaskUpdatedMessage(message);
            break;
        case "TASK_DELETED":
            scwin.handleTaskDeletedMessage(message);
            break;
        case "TASK_CREATED":
            scwin.handleTaskCreatedMessage(message);
            break;
        case "BOARD_CREATED":
            scwin.handleBoardCreatedMessage(message);
            break;
        case "BOARD_DELETED":
            scwin.handleBoardDeletedMessage(message);
            break;
    }
};

/**
 * 카드 이동 메시지 처리 (다른 사용자의 실시간 카드 이동 반영)
 */
scwin.handleCardMovedMessage = function (message) {

    // 중복 방지 로직 개선
    let currentUserId = scwin.getCurrentUserId();

    // CARD_MOVE (본인이 보낸 메시지)는 무시, CARD_MOVED (서버 브로드캐스트)는 처리
    if (message.type === "CARD_MOVE" && message.userId === currentUserId) {
        return;
    }
    // 메시지 유효성 검증
    if (!message.taskId || !message.toBoardId) {
        return;
    }

    // 실제 카드 이동 처리
    scwin.updateCardPositionFromMessage(message);
};

/**
 * 태스크 업데이트 메시지 처리 (다른 사용자의 실시간 태스크 수정 반영)
 */
scwin.handleTaskUpdatedMessage = function (message) {
    // 메시지 유효성 검증
    if (!message.taskId || !message.projectId) {
        return;
    }

    // 현재 프로젝트가 아니면 무시
    let currentProjectId = $p.getComponentById("dm_projectVo").get("projectId");

    if (message.projectId !== currentProjectId) {
        return;
    }

    try {
        // 현재 사용자의 변경사항인지 확인
        let currentUserId = scwin.getCurrentUserId();
        let isMyChange = (message.userId && message.userId === currentUserId);

        if (!isMyChange) {

            // 해당 보드 데이터 새로고침 (다른 사용자의 변경사항만)
            if (message.boardId && scwin.refreshBoardData) {            
                try {
                    scwin.refreshBoardData(message.boardId);
                } catch (refreshErr) {
                }
            } else {
            }
        } else {
        }

        // 1. 로컬 캐시 데이터 업데이트
        scwin.updateLocalTaskCache(message);

        // 2. 칸반 보드의 해당 카드 업데이트
        scwin.updateKanbanCardFromMessage(message);

        // 3. 열려있는 태스크 모달이 해당 태스크라면 새로고침 알림
        scwin.checkAndNotifyOpenTaskModal(message);
    } catch (error) {
    }
};

/**
 * 로컬 태스크 캐시 데이터 업데이트
 */
scwin.updateLocalTaskCache = function (message) {
    if (scwin.allTasksData && scwin.allTasksData.length > 0) {
        for (let i = 0; i < scwin.allTasksData.length; i++) {
            let task = scwin.allTasksData[i];
            if (task.taskId === message.taskId) {
                // 업데이트된 속성들을 로컬 캐시에 반영
                if (message.taskTitle !== undefined) task.taskTitle = message.taskTitle;
                if (message.priority !== undefined) task.priority = message.priority;
                if (message.startDate !== undefined) task.startDate = message.startDate;
                if (message.endDate !== undefined) task.endDate = message.endDate;
                if (message.tags !== undefined) task.tags = message.tags;
                if (message.boardId !== undefined) task.boardId = message.boardId;

                break;
            }
        }
    }
};

/**
 * 칸반 보드의 카드 업데이트
 */
scwin.updateKanbanCardFromMessage = function (message) {
    try {
        // 칸반 보드에서 해당 태스크 카드 찾기
        let cardElement = document.querySelector('[data-task-id="' + message.taskId + '"]');
        if (cardElement) {
            // 카드 제목 업데이트
            if (message.taskTitle !== undefined) {
                let titleElement = cardElement.querySelector('.card-title');
                if (titleElement) {
                    titleElement.textContent = message.taskTitle;
                }
            }

            // 우선순위 배지 업데이트
            if (message.priority !== undefined) {
                let priorityElement = cardElement.querySelector('.priority-badge');
                if (priorityElement) {
                    priorityElement.className = 'priority-badge priority-' + (message.priority || 'none');
                    priorityElement.textContent = message.priority || '';
                }
            }

            // 날짜 정보 업데이트
            if (message.startDate !== undefined || message.endDate !== undefined) {
                let dateElement = cardElement.querySelector('.task-dates');
                if (dateElement && (message.startDate || message.endDate)) {
                    let dateText = '';
                    if (message.startDate && message.endDate) {
                        dateText = message.startDate + ' ~ ' + message.endDate;
                    } else if (message.startDate) {
                        dateText = '시작: ' + message.startDate;
                    } else if (message.endDate) {
                        dateText = '마감: ' + message.endDate;
                    }
                    dateElement.textContent = dateText;
                }
            }

            // 카드에 업데이트 애니메이션 효과 추가
            cardElement.style.boxShadow = '0 0 10px rgba(0, 123, 255, 0.5)';
            setTimeout(function() {
                cardElement.style.boxShadow = '';
            }, 2000);

        } else {
        }
    } catch (error) {
    }
};

/**
 * 열려있는 태스크 모달 확인 및 알림
 */
scwin.checkAndNotifyOpenTaskModal = function (message) {
    try {
        // 현재 열려있는 팝업이 해당 태스크의 모달인지 확인
        let openPopups = $p.getPopupList();
        for (let i = 0; i < openPopups.length; i++) {
            let popup = openPopups[i];
            if (popup.id === "exa_popup" && popup.dataObject && popup.dataObject.data) {
                let popupTaskId = popup.dataObject.data.taskId;
                if (popupTaskId === message.taskId) {
                    break;
                }
            }
        }
    } catch (error) {
    }
};

/**
 * 태스크 삭제 메시지 처리 (다른 사용자의 실시간 태스크 삭제 반영)
 */
scwin.handleTaskDeletedMessage = function (message) {
    // 메시지 유효성 검증
    if (!message.taskId || !message.projectId) {
        return;
    }

    // 현재 프로젝트가 아니면 무시
    let currentProjectId = $p.getComponentById("dm_projectVo").get("projectId");
    if (message.projectId !== currentProjectId) {
        return;
    }

    try {
        // 1. 로컬 캐시 데이터에서 제거
        scwin.removeTaskFromLocalCache(message.taskId);

        // 2. 칸반 보드에서 해당 카드 제거
        scwin.removeKanbanCardFromUI(message.taskId);

        // 3. 열려있는 태스크 모달이 해당 태스크라면 닫기
        scwin.closeOpenTaskModalIfMatches(message.taskId);    
    } catch (error) {
    }
};

/**
 * 보드 생성 메시지 수신 처리
 */
scwin.handleBoardCreatedMessage = function (message) {

    // 메시지 유효성 검증
    if (!message.boardId || !message.projectId) {
        return;
    }

    // 중복 메시지 처리 방지
    let messageId = message.type + "_" + message.boardId + "_" + message.projectId + "_" + message.timestamp;
    if (scwin.processedMessages.has(messageId)) {
        return;
    }
    scwin.processedMessages.add(messageId);

    // 메시지 처리 개수 제한 (메모리 관리)
    if (scwin.processedMessages.size > 100) {
        scwin.processedMessages.clear();
    }

    // 현재 프로젝트가 아니면 무시
    let currentProjectId = $p.getComponentById("dm_projectVo").get("projectId");
    if (message.projectId !== currentProjectId) {
        return;
    }

    // 현재 사용자 확인 (자신이 생성한 보드는 이미 화면에 있을 수 있음)
    let currentUserId = scwin.getCurrentUserId();

    try {
        // 새로운 보드를 동적으로 추가
        scwin.addNewBoardColumn(message);

    } catch (error) {
        scwin.refreshBoardList();
    }
};

/**
 * 새로운 보드 컬럼을 실시간으로 추가
 */
scwin.addNewBoardColumn = function (message) {
    try {    
        // 1. 데이터 모델에 새 보드 추가
        let boardListComponent = $p.getComponentById("dlt_boardListVo");
        // 새 보드 데이터 생성 (message.message에 보드 제목이 들어있음)
        let actualBoardId = message.boardId;

        let newBoardData = {
            boardId: actualBoardId,
            boardTitle: message.message || message.boardTitle || "새 보드",
            projectId: message.projectId
        };

        // 중복 체크: 같은 boardId가 이미 존재하는지 확인
        let existingBoard = false;
        for (let i = 0; i < boardListComponent.getRowCount(); i++) {
            let existingBoardId = boardListComponent.getCellData(i, "boardId");
            if (existingBoardId === actualBoardId) {
                existingBoard = true;
                break;
            }
        }

        if (existingBoard) {
            return; // 이미 존재하면 함수 종료
        }

        // UI에서도 중복 체크
        let columnId = "grp_dynamic_" + actualBoardId;
        let existingColumn = $p.getComponentById(columnId);
        if (existingColumn) {
            return;
        }

        // 데이터 리스트에 추가
        let rowIndex = boardListComponent.insertRow();
        boardListComponent.setCellData(rowIndex, "boardId", newBoardData.boardId);
        boardListComponent.setCellData(rowIndex, "boardTitle", newBoardData.boardTitle);
        boardListComponent.setCellData(rowIndex, "projectId", newBoardData.projectId);

        // 2. 칸반 컨테이너 찾기
        let kanbanContainer = $p.getComponentById("grp_kanban_board");

        // 3. 새 보드 컬럼 동적 생성
        let boardIndex = boardListComponent.getRowCount() - 1; // 마지막에 추가된 인덱스
        scwin.createSingleKanbanColumn(newBoardData, boardIndex, kanbanContainer);

        // 4. 드롭 존 및 이벤트 바인딩 갱신
        setTimeout(function() {
            try {
                scwin.setupDropZoneAsync();
                scwin.bindAddCardEvents();
            } catch (bindError) {
            }
        }, 100);

    } catch (error) {
        throw error; // 상위 에러 처리로 전달
    }
};

/**
 * 보드 목록 새로고침
 */
scwin.refreshBoardList = function () {
    try {

        // 보드 목록을 다시 로드
        if (typeof $p.executeSubmission === "function") {
            $p.executeSubmission("load_Boards");
        } else {
        }

    } catch (error) {
    }
};
scwin.deleteBoardConfirmCallback = function(result) {
      if (result) {
          // 확인 클릭 시
          scwin.deleteBoard(scwin.pendingDeleteBoardId, scwin.pendingDeleteBoardTitle);
      } else {
      }
      // 임시 변수 정리
      scwin.pendingDeleteBoardId = null;
      scwin.pendingDeleteBoardTitle = null;
  };

/**
 * 보드 삭제 확인 및 실행
 */
scwin.confirmAndDeleteBoard = function (boardId, boardTitle) {
    try {
        // 확인 메시지
        let confirmMessage = "'" + boardTitle + "' 보드를 삭제하시겠습니까?\n\n" +
                           "이 작업은 되돌릴 수 없으며, 보드 내의 모든 카드가 함께 삭제됩니다.";

        scwin.pendingDeleteBoardId = boardId;
        scwin.pendingDeleteBoardTitle = boardTitle;
        $c.win.confirm(confirmMessage, "scwin.deleteBoardConfirmCallback");
    } catch (error) {
    }
};

/**
 * 보드 삭제 실행
 */
scwin.deleteBoard = function (boardId, boardTitle) {
    try {
        // 현재 프로젝트 ID 가져오기
        let projectId = $p.parent().dm_projectVo.get("projectId");

        // 삭제 요청 데이터 설정
        dm_boardVo.set("boardId", boardId);
        dm_boardVo.set("projectId", projectId);

        // 서버에 삭제 요청
        $p.executeSubmission("delete_board");

    } catch (error) {
    }
};

/**
 * 태스크 생성 메시지 수신 처리
 */
scwin.handleTaskCreatedMessage = function (message) {

    // 메시지 유효성 검증
    if (!message.taskId || !message.boardId || !message.projectId) {
        return;
    }

    // 중복 메시지 처리 방지
    let messageId = message.type + "_" + message.taskId + "_" + message.projectId + "_" + message.timestamp;
    if (scwin.processedMessages.has(messageId)) {
        return;
    }
    scwin.processedMessages.add(messageId);

    // 현재 프로젝트가 아니면 무시
    let currentProjectId = $p.parent().dm_projectVo.get("projectId");
    if (message.projectId !== currentProjectId) {
        return;
    }

    try {
        // 새 카드를 동적으로 생성하여 해당 보드에 추가
        scwin.addNewTaskCardToBoardDynamically(message);    
    } catch (error) {
        // 에러가 발생하면 전체 새로고침으로 폴백
        try {
            scwin.refreshKanbanBoard();
        } catch (refreshError) {
        }
    }
};

/**
 * 새로운 태스크 카드를 동적으로 보드에 추가하는 함수
 * @param {Object} message - 태스크 생성 메시지 (taskId, boardId, taskTitle, priority 등)
 */
scwin.addNewTaskCardToBoardDynamically = function (message) {
    try {
        // 2. 해당 보드의 카드 컨테이너 찾기
        let boardId = message.boardId;
        let cardsContainer = document.querySelector(`[data-board-id="${boardId}"].kanban-cards-container`);

        if (!cardsContainer) {
            throw new Error(`보드 ${boardId}의 카드 컨테이너를 찾을 수 없음`);
        }

        // 3. 태스크 데이터 구성 (기존 createKanbanCardInBoard와 호환되도록)
        let taskData = {
            taskId: message.taskId,
            taskTitle: message.taskTitle || message.message, // taskTitle 우선, 없으면 message 사용
            boardId: message.boardId,
            projectUserId: message.projectUserId || '', // projectUserId 추가
            priority: message.priority || 'MEDIUM',
            startDate: message.startDate || null,
            endDate: message.endDate || null,
            tags: message.tags || null,
            userName: message.userName || '' // 사용자 이름
        };

        // 4. 기존 함수를 사용하여 카드 생성
        scwin.createKanbanCardInBoard(taskData);

    } catch (error) {
        throw error; // 상위에서 폴백 처리할 수 있도록 에러 재발생
    }
};

/**
 * 보드 삭제 메시지 처리 (실시간 동기화)
 */
scwin.handleBoardDeletedMessage = function (message) {
    // 메시지 유효성 검증
    if (!message.boardId || !message.projectId) {
        return;
    }

    // 현재 프로젝트가 아니면 무시
    let currentProjectId = $p.getComponentById("dm_projectVo").get("projectId");
    if (message.projectId !== currentProjectId) {
        return;
    }

    try {
        // 실시간으로 보드 컬럼 제거
        scwin.removeBoardColumn(message);

    } catch (error) {
        scwin.refreshBoardList();
    }
};

/**
 * 보드 컬럼을 실시간으로 제거
 */
scwin.removeBoardColumn = function (message) {
    try {

        // 1. 데이터 모델에서 보드 제거
        let boardListComponent = $p.getComponentById("dlt_boardListVo");
        if (!boardListComponent) {
            throw new Error("보드 데이터 리스트를 찾을 수 없음");
        }

        // 삭제할 보드의 인덱스 찾기
        let boardIndex = -1;
        for (let i = 0; i < boardListComponent.getRowCount(); i++) {
            let boardId = boardListComponent.getCellData(i, "boardId");
            if (boardId === message.boardId) {
                boardIndex = i;
                break;
            }
        }

        if (boardIndex === -1) {
        } else {
            // 데이터 모델에서 행 삭제
            boardListComponent.removeRow(boardIndex);
        }

        // 2. UI에서 보드 컬럼 제거
        let columnId = "grp_dynamic_" + message.boardId;
        let boardColumn = $p.getComponentById(columnId);

        if (boardColumn) {
            // 삭제 애니메이션 효과
            try {
                let columnElement = boardColumn.getElement();
                if (columnElement) {
                    columnElement.style.transition = 'all 0.3s ease-out';
                    columnElement.style.transform = 'scale(0)';
                    columnElement.style.opacity = '0';

                    // 애니메이션 완료 후 컴포넌트 제거
                    setTimeout(function() {
                        try {
                            boardColumn.destroy();
                        } catch (destroyError) {
                        }
                    }, 300);
                } else {
                    // 애니메이션 없이 바로 제거
                    boardColumn.destroy();
                }
            } catch (animationError) {
                boardColumn.destroy();
            }
        } else {
        }

    } catch (error) {
        throw error; // 상위 에러 처리로 전달
    }
};

/**
