/**
 * 카드 이동 메시지 전송
 */
scwin.sendCardMoveMessage = function (taskId, fromBoardId, toBoardId) {
    // 현재 프로젝트 ID 가져오기
    let projectId = null;
    if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
        projectId = scwin.currentProjectData.projectId;
    } else {
        // 프로젝트 데이터가 없으면 URL에서 추출 시도
        let urlParams = new URLSearchParams(window.location.search);
        projectId = urlParams.get('projectId');
    }

    let currentUserId = scwin.getCurrentUserId();

    let message = {
        type: "CARD_MOVE",
        taskId: taskId,
        fromBoardId: fromBoardId,
        toBoardId: toBoardId,
        projectId: projectId,
        userId: currentUserId,
        timestamp: Date.now()
    };

    scwin.sendWebSocketMessage(message);
};

