/**
 * 사용자 역할 확인 후 프로젝트 설정 버튼 제어
 */
scwin.checkUserPermissionForSettings = function() {

    try {
        let userId = scwin.getCurrentUserId();
        let projectId = scwin.currentProjectData ? scwin.currentProjectData.projectId : null;

        // 프로젝트 ID가 없으면 URL에서 가져오기 시도
        if (!projectId) {
            try {
                let urlParams = new URLSearchParams(window.location.search);
                projectId = urlParams.get('projectId');
            } catch (e) {

            }
        }

        if (!userId || !projectId) {
            // 기본적으로 버튼을 숨김
            scwin.hideSettingsButton();
            return;
        }

        // 백엔드 API 호출
        $.ajax({
            type: "GET",
            url: "/InsWebApp/checkUserRole.pwkjson",
            data: {
                userId: userId,
                projectId: projectId
            },
            dataType: "json",
            success: function(data) {      
                if (data.success && data.isAdmin) {

                    scwin.showSettingsButton();
                } else {

                    scwin.hideSettingsButton();
                }
            },
            error: function(xhr, status, error) {
                // 오류 시 기본적으로 버튼을 숨김
                scwin.hideSettingsButton();
            }
        });
    } catch (e) {
        scwin.hideSettingsButton();
    }
};

