/**
 * 모든 태그 선택/해제 토글
 */
scwin.selectAllTags = function () {
    // 현재 모든 태그가 선택되어 있는지 확인
    let isAllSelected = scwin.availableTags.every(function (tag) {
        return scwin.selectedTags.indexOf(tag) > -1;
    });

    if (isAllSelected) {
        // 모든 태그가 선택되어 있으면 전체 해제
