/**
 * 클라이언트에서 태스크 목록 정렬 (서버 정렬이 제대로 되지 않는 경우 대비)
 */
scwin.sortTasksOnClient = function(tasks, sortField, sortOrder) {
    if (!tasks || tasks.length === 0) {
        return tasks;
    }


    // 기본값 설정
    if (!sortField) sortField = "startDate";
    if (!sortOrder) sortOrder = "asc";

    // 태스크 배열 복사 (원본 변경 방지)
    let sortedTasks = tasks.slice();

    sortedTasks.sort(function(a, b) {
        let valueA = a[sortField];
        let valueB = b[sortField];

        // null 또는 undefined 처리 - 빈값은 뒤로 정렬
        if (!valueA && !valueB) return 0;
        if (!valueA) return 1; // A가 null이면 뒤로 (A > B)
        if (!valueB) return -1; // B가 null이면 A를 앞으로 (A < B)

        try {
            // 날짜 필드인 경우 날짜로 파싱하여 비교
            if (sortField === "startDate" || sortField === "endDate") {
                let dateA = scwin.parseTaskDate(valueA);
                let dateB = scwin.parseTaskDate(valueB);

                let comparison = dateA.getTime() - dateB.getTime();
                return sortOrder === "desc" ? -comparison : comparison;
            } else {
                // 문자열 비교
                let strA = valueA.toString().toLowerCase();
                let strB = valueB.toString().toLowerCase();

                let comparison = strA.localeCompare(strB);
                return sortOrder === "desc" ? -comparison : comparison;
            }
        } catch (error) {
            // 오류 발생 시 문자열 비교로 폴백
            let comparison = valueA.toString().localeCompare(valueB.toString());
            return sortOrder === "desc" ? -comparison : comparison;
        }
    });

    return sortedTasks;
};

/**
 * 태스크 날짜 문자열을 Date 객체로 파싱
 */
scwin.parseTaskDate = function(dateStr) {
    if (!dateStr) return new Date(0); // 1970-01-01

    try {
        // 다양한 날짜 형식 지원
        // "2024-01-15", "2024/01/15", "20240115" 등
        let cleanDateStr = dateStr.toString().trim();

        // YYYYMMDD 형식인 경우 YYYY-MM-DD로 변환
        if (/^\d{8}$/.test(cleanDateStr)) {
            cleanDateStr = cleanDateStr.substring(0, 4) + "-" + 
                          cleanDateStr.substring(4, 6) + "-" + 
                          cleanDateStr.substring(6, 8);
        }

        let date = new Date(cleanDateStr);

        // 유효한 날짜인지 확인
        if (isNaN(date.getTime())) {
            return new Date(0);
        }

        return date;
    } catch (error) {
        return new Date(0);
    }
};

/**
 * 정렬과 필터링을 모두 적용 (수정된 버전)
 */
scwin.applySortAndFilter = function () {

    // 모든 보드에 대해 서버에서 정렬된 데이터 요청
    let boardList = $p.getComponentById("dlt_boardListVo");
    if (boardList && boardList.getRowCount() > 0) {

        // 모든 태스크 데이터 초기화 (새로운 정렬로 재로드)
        scwin.allTasksData = {};

        // 성공한 보드 요청 수 추적 초기화
        scwin.sortRequestCount = 0;
        scwin.expectedSortRequests = boardList.getRowCount();

        for (let i = 0; i < boardList.getRowCount(); i++) {
            let boardId = boardList.getCellData(i, "boardId");
            let boardTitle = boardList.getCellData(i, "boardTitle");

            if (boardId) {
                // 서버에 정렬 파라미터와 함께 요청
                scwin.loadTasksWithSort(boardId);
            }
        }
    } else {
        // 기존 데이터를 태그 필터링만 다시 적용
        scwin.applyTagFilterToExistingData();
    }

};

/**
 * 기존 데이터에 태그 필터링만 적용 (서버 요청 없이)
 */
scwin.applyTagFilterToExistingData = function () {

    let boardList = $p.getComponentById("dlt_boardListVo");
    if (boardList && boardList.getRowCount() > 0) {
        for (let i = 0; i < boardList.getRowCount(); i++) {
            let boardId = boardList.getCellData(i, "boardId");
            if (boardId && scwin.allTasksData[boardId]) {
                scwin.sortAndFilterBoardTasks(boardId);
            }
        }
    }
};

/**
 * 특정 보드에 대해 정렬된 태스크 데이터를 서버에서 로드 (수정된 버전)
 */
scwin.loadTasksWithSort = function (boardId) {

    // 중복 호출 방지
    if (scwin.isTaskListWithUserNameLoading) {
        return;
    }

    try {
        // 검색 조건에 정렬 파라미터 추가 (안전한 접근 방식)
        if (typeof dm_search_task !== 'undefined') {
            dm_search_task.set("boardId", boardId);
            dm_search_task.set("sortField", scwin.currentSortField);
            dm_search_task.set("sortOrder", scwin.currentSortOrder);
        } else {
            // 대안: $p.getComponentById 사용
            let searchCondition = $p.getComponentById("dm_search_task");
            if (searchCondition) {
                searchCondition.set("boardId", boardId);
                searchCondition.set("sortField", scwin.currentSortField);
                searchCondition.set("sortOrder", scwin.currentSortOrder);
            } else {
                throw new Error("dm_search_task 컴포넌트를 찾을 수 없습니다.");
            }
        }

        // 서버 요청 (중복 호출 방지 플래그 설정)
        scwin.isTaskListWithUserNameLoading = true;

        $p.executeSubmission("load_Tasks_With_UserName");

    } catch (error) {
        // 에러 발생 시 플래그 해제
        scwin.isTaskListWithUserNameLoading = false;
    }
};

/**
 * 특정 보드의 태스크에 태그 필터링만 적용 (정렬은 서버에서 처리됨)
 */
scwin.sortAndFilterBoardTasks = function (boardId) {

    // 해당 보드의 전체 태스크 데이터 가져오기 (이미 서버에서 정렬된 상태)
    let allTasks = scwin.allTasksData[boardId] || [];

    // 원본 태스크 데이터가 없는 경우 경고
    if (allTasks.length === 0) {
        // 빈 데이터라도 화면에 표시 (기존 카드 제거를 위해)
        scwin.displayFilteredTasks(boardId, []);
        return;
    }

    // 디버깅: 태스크 상세 정보 출력 (서버에서 이미 정렬된 상태)
    for (let idx = 0; idx < Math.min(allTasks.length, 3); idx++) {
        let task = allTasks[idx];
    }
    if (allTasks.length > 3) {
    }

    // 태그 필터링만 적용 (정렬은 이미 서버에서 처리됨)
    let filteredTasks = [];
    if (scwin.selectedTags.length === 0) {
        // 선택된 태그가 없으면 모든 태스크 표시 (서버 정렬 순서 유지)
        filteredTasks = allTasks;
    } else {
        // 선택된 태그가 있으면 필터링 (서버 정렬 순서 유지)
        for (let i = 0; i < allTasks.length; i++) {
            let task = allTasks[i];
            if (scwin.isTaskMatchesTags(task, scwin.selectedTags)) {
                filteredTasks.push(task);
            }
        }
    }


    // 화면에 표시 (이미 서버에서 정렬된 데이터)
    scwin.displayFilteredTasks(boardId, filteredTasks);
};

