                        let isVisible = false;
                        if (grp_gantt_view) {
                            if (typeof grp_gantt_view.isVisible === 'function') {
                                isVisible = grp_gantt_view.isVisible();
                            } else {
                                // 안전한 fallback - 항상 로드
                                isVisible = true;
                            }
                        }
                        if (isVisible) {
                            scwin.loadGanttData();
                        }
                    } catch (error) {
                        // 오류 발생 시 안전하게 데이터 로드
                        scwin.loadGanttData();
                    }
                } else {
                    // fallback: 기존 방식 사용
                    if (typeof scwin.loadTasksWithUserName === 'function') {
                        scwin.loadTasksWithUserName();
                        // 태스크 로드 완료 후 간트차트 로드 (비동기)
                        setTimeout(function () {
                            // 간트 뷰 가시성을 안전하게 확인
                            try {
                                let isVisible = false;
                                if (grp_gantt_view) {
                                    if (typeof grp_gantt_view.isVisible === 'function') {
                                        isVisible = grp_gantt_view.isVisible();
                                    } else {
                                        // 안전한 fallback - 항상 로드
                                        isVisible = true;
                                    }
                                }
                                if (isVisible) {
                                    scwin.loadGanttData();
                                }
                            } catch (error) {
                                // 오류 발생 시 안전하게 데이터 로드
                                scwin.loadGanttData();
                            }
                        }, 1000);
                    } else {
                        // 기본 간트차트 데이터 로딩
                        scwin.loadGanttData();
                    }
                }
            } catch (error) {
                scwin.loadGanttData();
            }
        }
    }
};

// 캘린더 보기 버튼 클릭
scwin.calendar_onclick = function (e) {

    // 데이터 존재 여부 미리 확인 (성능 최적화)
    let hasData = false;
    if (scwin.allTasksData) {
        for (let boardId in scwin.allTasksData) {
            if (scwin.allTasksData[boardId] && scwin.allTasksData[boardId].length > 0) {
                hasData = true;
                break;
            }
        }
    }


    // 칸반 보드 숨기기
    let kanbanBoard = $p.getComponentById("grp_kanban_board");
    if (kanbanBoard) {
        kanbanBoard.hide();
    }

    // 간트차트 영역 숨기기
    let ganttView = $p.getComponentById("grp_gantt_view");
    if (ganttView) {
        ganttView.hide();
    }

    // 캘린더 영역 표시
    let calendarView = $p.getComponentById("grp_calendar_view");
    if (calendarView) {
        calendarView.show();
    }

    // 메인 콘텐츠 overflow 설정 (캘린더: hidden)
    let mainContent = $p.getComponentById("mf_grp_mainContent");
    if (mainContent) {
        mainContent.setStyle("overflow", "hidden");
    }

    // 태스크 데이터를 캘린더 형식으로 변환하여 로드
    if (hasData) {
        scwin.loadTasksToCalendar();
    } else {
        // 빈 데이터로 캘린더 초기화
        let calendarDataList = $p.getComponentById("dlt_calendar_schedule");
        if (calendarDataList) {
            calendarDataList.removeAll();
        }
    }
};

/**
 * 태스크 데이터를 캘린더 형식으로 변환하여 로드 (고성능 JSON 방식)
 */
scwin.loadTasksToCalendar = function () {

    // 캘린더 데이터 리스트 가져오기
    let calendarDataList = $p.getComponentById("dlt_calendar_schedule");
    if (!calendarDataList) {
        return;
    }

    // allTasksData에서 데이터 수집
    let allTasks = [];
    if (scwin.allTasksData) {
        for (let boardId in scwin.allTasksData) {
            if (scwin.allTasksData.hasOwnProperty(boardId)) {
                let boardTasks = scwin.allTasksData[boardId];
                if (boardTasks && boardTasks.length > 0) {
                    allTasks = allTasks.concat(boardTasks);
                }
            }
        }
    }


    // 색상 배열
    let colors = [
        "#FF6B6B", "#4ECDC4", "#45B7D1", "#96CEB4", "#FFEAA7", "#DDA0DD", 
        "#98D8C8", "#F7DC6F", "#FF8A65", "#81C784", "#64B5F6", "#FFB74D", 
        "#BA68C8", "#4DB6AC", "#A1C181", "#F48FB1"
    ];

    // 캘린더 데이터 JSON 배열 생성 (고성능)
    let calendarJsonData = [];
    for (let i = 0; i < allTasks.length; i++) {
        let task = allTasks[i];

        // 시작일이 있는 태스크만 포함
        if (task.startDate) {
            let startDate = scwin.formatDateForCalendar(task.startDate);
            let endDate = task.endDate ? scwin.formatDateForCalendar(task.endDate) : startDate;
            let backgroundColor = colors[i % colors.length];

            // themeColumn JSON 생성
            let themeJson = JSON.stringify({
                "backgroundColor": backgroundColor,
                "borderColor": backgroundColor,
                "textColor": "#FFFFFF"
            });

            // 캘린더 행 데이터 생성
            calendarJsonData.push({
                "id": task.taskId,
                "title": task.taskTitle || "제목 없음",
                "start": startDate,
                "end": endDate,
                "boardId": task.boardId,
                "boardTitle": scwin.getBoardTitle(task.boardId),
                "priority": task.priority || "normal",
                "tags": task.tags || "",
                "theme": themeJson
            });
        }
    }


    // 한번에 JSON 데이터로 설정 (고성능)
    calendarDataList.setJSON(calendarJsonData);


    // 캘린더 컴포넌트 새로고침
    let calendarComponent = $p.getComponentById("calendar_schedule");
    if (calendarComponent && calendarComponent.refresh) {
        calendarComponent.refresh();
    }
};

/**
 * 날짜 형식을 캘린더에 맞게 변환 (YYYYMMDD 형식)
 * @param {String} dateString - 변환할 날짜 문자열
 * @returns {String} 변환된 날짜 문자열 (YYYYMMDD 형식)
 */
scwin.formatDateForCalendar = function (dateString) {
    if (!dateString) return "";

    // 날짜 형식이 이미 YYYYMMDD 형태인지 확인
    if (dateString.match(/^\d{8}$/)) {
        return dateString;
    }

    // 다른 형식의 날짜를 YYYYMMDD로 변환
    try {
        let date;

        // YYYY-MM-DD 형식인 경우
        if (dateString.match(/^\d{4}-\d{2}-\d{2}$/)) {
            date = new Date(dateString);
        } else {
            date = new Date(dateString);
        }

        if (isNaN(date.getTime())) {
            return dateString;
        }

        let year = date.getFullYear();
        let month = String(date.getMonth() + 1).padStart(2, '0');
        let day = String(date.getDate()).padStart(2, '0');

        return year + month + day; // YYYYMMDD 형식
    } catch (error) {
        return dateString;
    }
};

/**
 * 태스크 데이터를 간트차트로 변환하여 로드 (모든 태스크 row 표시, 해당 월 그래프만 표시)
 */
scwin.loadTasksToGantt = function (allTasks, displayYear, displayMonth) {

    if (!gantt_chart_unique) {
        return;
    }

    // 기존 FusionCharts 객체 확인 (중복 방지)
    try {
        let existingChart = gantt_chart_unique.fc();
        if (existingChart) {
            // 기존 객체 정리하지 않고 재사용
        }
    } catch (e) {
    }

    // 간트차트 데이터 리스트에서 태스크 데이터 가져오기
    // 기존 차트 초기화 (간트차트.txt 권장 방법)
    try {
        // clear() 메소드는 공식 문서에 없으므로 setJSONData로 초기화
    } catch (e) {
    }

    // 전달받은 전체 태스크 또는 dlt_gantt_schedule에서 가져오기
    let ganttTasks = allTasks || dlt_gantt_schedule.getAllJSON();

    if (!ganttTasks || ganttTasks.length === 0) {

        // 전체 scwin.taskList를 사용
        if (!scwin.taskList || scwin.taskList.length === 0) {
            // 빈 배열로 설정하여 더미 데이터가 생성되도록 함
            ganttTasks = [];
        } else {
            // 전체 taskList 데이터를 사용 (모든 태스크 표시)
            ganttTasks = scwin.taskList.filter(function (task) {
                return task.startDate && task.endDate &&
                    task.startDate.trim() !== "" && task.endDate.trim() !== "";
            });

        }
    }


    // 전체 태스크를 해당 월 우선으로 정렬 (해당 월 태스크 위쪽, 나머지 아래쪽)
    if (ganttTasks && ganttTasks.length > 0) {
        let currentYear = displayYear || scwin.currentGanttYear || (new Date()).getFullYear();
        let currentMonth = displayMonth || scwin.currentGanttMonth || ((new Date()).getMonth() + 1);

        // 해당 월의 시작일과 종료일 계산
        let monthStart = new Date(currentYear, currentMonth - 1, 1);
        let monthEnd = new Date(currentYear, currentMonth, 0);

        // 1단계: 유효한 날짜를 가진 태스크만 필터링
        let validTasks = ganttTasks.filter(function(task) {
            // 시작날짜와 종료날짜가 모두 존재하고 비어있지 않은 경우만
            if (!task.startDate || !task.endDate || 
                task.startDate.trim() === "" || task.endDate.trim() === "") {
                return false;
            }

            // 날짜 파싱이 가능한 경우만
            let startDate = scwin.parseValidDate(task.startDate);
            let endDate = scwin.parseValidDate(task.endDate);
            if (!startDate || !endDate) {
                return false;
            }

            return true;
        });


        // 2단계: 해당 월 태스크와 다른 월 태스크로 분리
        let currentMonthTasks = [];
        let otherMonthTasks = [];

        validTasks.forEach(function(task) {
            let startDate = scwin.parseValidDate(task.startDate);
            let endDate = scwin.parseValidDate(task.endDate);

            // 해당 월과 겹치는지 확인 (시작일이 월 종료일 이전이고, 종료일이 월 시작일 이후)
            let isOverlapping = startDate <= monthEnd && endDate >= monthStart;

            if (isOverlapping) {
                currentMonthTasks.push(task);
            } else {
                otherMonthTasks.push(task);
            }
        });

        // 3단계: 각 그룹을 시작날짜 순으로 정렬
        currentMonthTasks.sort(function(a, b) {
            let dateA = scwin.parseValidDate(a.startDate);
            let dateB = scwin.parseValidDate(b.startDate);
            return dateA.getTime() - dateB.getTime();
        });

        otherMonthTasks.sort(function(a, b) {
            let dateA = scwin.parseValidDate(a.startDate);
            let dateB = scwin.parseValidDate(b.startDate);
            return dateA.getTime() - dateB.getTime();
        });

        // 4단계: 해당 월 태스크를 위에, 다른 월 태스크를 아래에 배치
        ganttTasks = currentMonthTasks.concat(otherMonthTasks);

    }

    // 스크롤 컨테이너 사용으로 높이를 자연스럽게 증가 (최대 높이 제한 없음)
    let taskCount = ganttTasks.length;
    let baseHeight = 150;  // 기본 높이
    let taskHeight = 45;   // 태스크당 높이 (더 여유있게)
    let minHeight = 400;   // 최소 높이 (스크롤 컨테이너 내에서)

    let dynamicHeight = Math.max(minHeight, baseHeight + (taskCount * taskHeight));


    try {
        // 스크롤 컨테이너 내에서 자연스러운 높이 설정
        gantt_chart_unique.setStyle("height", dynamicHeight + "px");
    } catch (sizeError) {
    }

    // 간트차트.txt 방식으로 데이터 설정

    // 1. 기본 차트 속성 설정 (간트차트.txt 형식)
    let chartOptions = {
        caption: "",  // 제목 제거
        dateformat: "mm/dd/yyyy",
        outputdateformat: "mm/dd/yyyy",


        showTaskNames: "1",
        showTaskLabels: "0",
        showConnectors: "0",
        taskBarFillMix: "",
        taskBarFillRatio: "",
        // 전역 그림자 효과 제거
        showBorder: "1",
        borderThickness: "1",

        showShadow: "0",
        dropShadow: "0"
    };
    gantt_chart_unique.setChartAttribute(chartOptions);

    // 2. 카테고리 설정 (해당 월의 일별 카테고리만 표시)
    let currentDate = new Date();
    let currentYear = displayYear || scwin.currentGanttYear || currentDate.getFullYear();
    let currentMonth = displayMonth || scwin.currentGanttMonth || (currentDate.getMonth() + 1);

    let categoryData = scwin.createMonthlyCategories(currentYear, currentMonth);
    if (categoryData) {
        gantt_chart_unique.setCategories(categoryData);
    }

    // 3. processes와 tasks 데이터 생성 (년/월 정보 전달)
    let ganttJSONData = scwin.createGanttJSONFromDataList_backup(ganttTasks, currentYear, currentMonth);

    // 4. JSON 데이터 설정
    if (ganttJSONData) {
        gantt_chart_unique.setJSONData(ganttJSONData);
    }

    // 5. 색상 설정은 일단 건너뛰기 (processes 표시 테스트)

    // 6. 간트차트 그리기
    gantt_chart_unique.draw();

    // 최종적으로 차트 강제 다시 그리기
    try {
        if (typeof gantt_chart_unique.draw === 'function') {
            gantt_chart_unique.draw();
        }
    } catch (drawError) {
    }

};


/**
 * 특정 월의 카테고리만 생성
 */
scwin.createMonthlyCategories = function (year, month) {
    let firstDay = new Date(year, month - 1, 1);
    let lastDay = new Date(year, month, 0);
    let totalDays = lastDay.getDate(); // 해당 월의 총 일수

    let dailyCategories = [];

    // FusionCharts가 인덱스 1부터 그리는 문제 해결을 위해 빈 칸 2개 추가
    // 첫 번째 빈 칸 (인덱스 0)
    // dailyCategories.push({
    //     start: "",
    //     end: "",
    //     label: ""
    // });

    // // 두 번째 빈 칸 (인덱스 1) - FusionCharts 오프셋 보정용
    // dailyCategories.push({
    //     start: "07/01/2025",
    //     end: "07/01/2025",
    //     label: "0"
    // });

    // 1부터 총일수까지 실제 날짜 카테고리 생성
    for (let day = 0; day <= totalDays; day++) {
        let currentDate = new Date(year, month - 1, day); // 실제 날짜

        dailyCategories.push({
            start: scwin.formatDate(currentDate),
            end: scwin.formatDate(currentDate),
            label: day.toString() // 라벨은 실제 날짜 (1, 2, 3, ..., 31)
        });
    }


    return { category: dailyCategories };
};

/**
 * 간트차트용 월별 + 일별 카테고리 생성 (2단계 카테고리)
 */
scwin.createGanttCategories = function (tasks) {
    if (!tasks || tasks.length === 0) {
        return null;
    }


    // 모든 태스크의 날짜 범위 수집
    let allDates = [];
    tasks.forEach(function (task) {
        if (task.startDate) allDates.push(new Date(task.startDate));
        if (task.endDate) allDates.push(new Date(task.endDate));
    });

    if (allDates.length === 0) {
        return null;
    }

    // 최소, 최대 날짜 구하기
    let minDate = new Date(Math.min.apply(null, allDates));
    let maxDate = new Date(Math.max.apply(null, allDates));


    // 주차별 카테고리 생성 (더 간단한 표시)
    let categories = [];
    let currentDate = new Date(minDate);

    // 시작일부터 종료일까지 주 단위로 카테고리 생성
    while (currentDate <= maxDate) {
        let weekStart = new Date(currentDate);
        let weekEnd = new Date(currentDate);
        weekEnd.setDate(weekEnd.getDate() + 6); // 7일 후

        // 마지막 주는 최대 날짜로 제한
        if (weekEnd > maxDate) {
            weekEnd = new Date(maxDate);
        }

        categories.push({
            start: scwin.formatToMMDDYYYY(weekStart),
            end: scwin.formatToMMDDYYYY(weekEnd),
            label: (weekStart.getMonth() + 1) + "/" + weekStart.getDate() +
                " ~ " + (weekEnd.getMonth() + 1) + "/" + weekEnd.getDate()
        });

        currentDate.setDate(currentDate.getDate() + 7); // 다음 주로
    }


    return { category: categories };
};

