/**
 * DataList에서 간트차트 JSON 데이터 생성 (모든 태스크 row 표시, 해당 월 그래프만 표시) - 백업용
 */
scwin.createGanttJSONFromDataList_backup = function (ganttTasks, displayYear, displayMonth) {
    if (!ganttTasks || ganttTasks.length === 0) {
        // 작고 투명한 더미 데이터 생성
        return scwin.createDummyGanttData(displayYear, displayMonth);
    }

    let processes = [];
    let tasks = [];

    // 해당 월의 시작일과 종료일 계산
    let monthStart = null;
    let monthEnd = null;
    if (displayYear && displayMonth) {
        monthStart = new Date(displayYear, displayMonth - 1, 1);
        monthEnd = new Date(displayYear, displayMonth, 0);
    }

    // processes와 tasks 데이터 생성
    ganttTasks.forEach(function (task, index) {
        // processes (왼쪽 태스크 목록) - 모든 태스크를 row로 표시
        processes.push({
            id: task.taskId,
            label: task.taskTitle
        });

        // tasks (간트 바) - 해당 월과 겹치는 태스크만 표시
        let taskStartDate = scwin.parseValidDate(task.startDate);
        let taskEndDate = scwin.parseValidDate(task.endDate);

        // 유효하지 않은 날짜인 경우 해당 태스크는 그래프에 표시하지 않음 (processes에는 이미 추가됨)
        if (!taskStartDate || !taskEndDate) {
            return; // forEach의 현재 반복만 건너뛰기
        }

        let shouldShowTask = true;
        let actualStartDate = taskStartDate;
        let actualEndDate = taskEndDate;

        if (monthStart && monthEnd) {
            // 태스크가 해당 월과 겹치는지 확인
            if (taskEndDate < monthStart || taskStartDate > monthEnd) {
                // 해당 월과 전혀 겹치지 않으면 태스크 바를 표시하지 않음
                shouldShowTask = false;
            } else {
                // 해당 월과 겹치는 부분만 표시하도록 날짜 조정
                if (taskStartDate < monthStart) {
                    actualStartDate = monthStart;
                }
                if (taskEndDate > monthEnd) {
                    actualEndDate = monthEnd;
                }
            }
        }

        if (shouldShowTask) {
            // 1칸씩 밀리는 문제 해결: 시작일만 1일 앞당기고 종료일은 원래대로 유지
            let adjustedStartDate = new Date(actualStartDate.getTime() - 24 * 60 * 60 * 1000);
            let adjustedEndDate = actualEndDate;  // 종료일은 원래대로 유지

            // hover 툴팁에 표시할 원래 날짜 정보
            let originalStartStr = scwin.convertToMMDDYYYY(actualStartDate);
            let originalEndStr = scwin.convertToMMDDYYYY(actualEndDate);
            let tooltipText = task.taskTitle + "<br/>기간: " + originalStartStr + " ~ " + originalEndStr;

            tasks.push({
                id: task.taskId,
                start: scwin.convertToMMDDYYYY(adjustedStartDate),
                end: scwin.convertToMMDDYYYY(adjustedEndDate),
                processid: task.taskId,
                label: "",  // 라벨 숨기기
                color: scwin.getTaskColorByIndex(index),  // 인덱스별 다른 색상
                tooltext: tooltipText,  // 커스텀 툴팁
                // 테두리 완전 투명하게 설정
                borderThickness: "0",
                borderAlpha: "0"
            });
        }
    });


    // 더미 태스크 제거 - processes만으로 표시 테스트

    // 간단한 간트차트 구조로 반환
    return {
        chart: {
            caption: "프로젝트 일정",
            dateformat: "mm/dd/yyyy",
            showprocessname: "1",
            ganttrowheight: "40"
        },
        processes: {
            process: processes
        },
        tasks: {
            task: tasks.length > 0 ? tasks : scwin.createDummyTasksForProcesses(processes, displayYear, displayMonth)
        }
    };
};

/**
 * processes가 있지만 tasks가 없을 때 더미 tasks 생성
 */
scwin.createDummyTasksForProcesses = function (processes, displayYear, displayMonth) {
    let currentDate = new Date();
    let year = displayYear || currentDate.getFullYear();
    let month = displayMonth || (currentDate.getMonth() + 1);


    let dummyTasks = [];

    // 날짜 매핑 테스트를 위한 여러 개의 더미 태스크 생성
    if (processes.length > 0) {
        let process = processes[0];

        // 1일짜리 태스크들로 각 날짜별 매핑 테스트
        let testDates = [1, 5, 10, 15, 20, 25];

        for (let i = 0; i < testDates.length && i < 3; i++) { // 최대 3개만
            let testDay = testDates[i];
            // 1칸씩 밀리는 문제 해결: 날짜를 1일 앞당겨서 생성
            let testDate = new Date(year, month - 1, testDay - 1);
            // 사용자가 의도한 원래 날짜
            let intentedDate = new Date(year, month - 1, testDay);

            dummyTasks.push({
                id: "test_mapping_" + testDay,
                processid: process.id,
                start: scwin.formatDate(testDate),
                end: scwin.formatDate(testDate),
                label: "",  // 빈 라벨
                color: "FFFFFF",  // 흰색
                alpha: "0",  // 완전 투명
                fontcolor: "FFFFFF",  // 흰색 글자
                fontsize: "1",  // 최소 글자 크기
                showlabel: "0",  // 라벨 숨김
                // 테두리 완전 투명하게 설정
                borderThickness: "0",
                borderColor: "FFFFFF", 
                borderAlpha: "0",
                // 그림자 효과 제거
                shadow: "0",
                // 추가 투명도 설정
                fillalpha: "0",
                // 호버 효과 제거
                showHoverEffect: "0"
            });

        }
    }

    return dummyTasks;
};

/**
 * 더미 간트차트 데이터 생성 (데이터 없을 때 차트 구조 표시용)
 */
scwin.createDummyGanttData = function (displayYear, displayMonth) {
    let currentDate = new Date();
    let year = displayYear || currentDate.getFullYear();
    let month = displayMonth || (currentDate.getMonth() + 1);


    return {
        processes: {
            process: [
                {
                    id: "dummy_process",
                    label: "데이터가 없습니다",
                    fontcolor: "#CCCCCC",
                    fontsize: "12"
                }
            ]
        },
        tasks: {
            task: [
                {
                    id: "dummy_task",
                    processid: "dummy_process",
                    start: scwin.formatDate(new Date(year, month - 1, 1)),
                    end: scwin.formatDate(new Date(year, month - 1, 1)),
                    label: "태스크를 추가해 주세요",
                    color: "#F5F5F5",
                    alpha: "20",
                    fontcolor: "#CCCCCC",
                    fontsize: "10"
                }
            ]
        }
    };
};

/**
 * 태스크 우선순위별 색상 반환 (로그아웃 버튼 색상으로 통일)
 */
/**
 * 인덱스별 다른 색상 반환 (각 태스크마다 다른 색상)
 */
scwin.getTaskColorByIndex = function (index) {
    let colors = [
        "#FF6B6B",  // 빨간색
        "#4ECDC4",  // 청록색  
        "#45B7D1",  // 파란색
        "#96CEB4",  // 초록색
        "#FFEAA7",  // 노란색
        "#DDA0DD",  // 자주색
        "#98D8C8",  // 민트색
        "#F7DC6F",  // 황금색
        "#FF8A65",  // 주황색
        "#81C784",  // 연한 초록색
        "#64B5F6",  // 연한 파란색
        "#FFB74D",  // 연한 주황색
        "#BA68C8",  // 연한 자주색
        "#4DB6AC",  // 청록색
        "#A1C181",  // 올리브색
        "#F48FB1"   // 핑크색
    ];

    return colors[index % colors.length];
};

scwin.getTaskColorByPriority = function (priority) {
    // 우선순위별 동적 색상 반환
    switch (priority) {
        case "HIGH":
            return "#FF6B6B";  // 빨간색 (고우선순위)
        case "MEDIUM":
            return "#4ECDC4";  // 청록색 (중우선순위)
        case "LOW":
            return "#95E1D3";  // 연한 청록색 (저우선순위)
        default:
            return "#A8E6CF";  // 기본 연한 초록색
    }
};

/**
 * 보드별 색상 반환 (대안 색상 스키마)
 */
scwin.getTaskColorByBoard = function (boardId) {
    let colors = [
        "#FF6B6B",  // 빨간색
        "#4ECDC4",  // 청록색  
        "#45B7D1",  // 파란색
        "#96CEB4",  // 초록색
        "#FFEAA7",  // 노란색
        "#DDA0DD",  // 자주색
        "#98D8C8",  // 민트색
        "#F7DC6F"   // 황금색
    ];

    // 보드 ID를 기반으로 색상 인덱스 계산
    let colorIndex = parseInt(boardId) % colors.length;
    return colors[colorIndex];
};

/**
 * yyyy-mm-dd 형식 또는 Date 객체를 mm/dd/yyyy 형식으로 변환 (간트차트.txt 형식)
 */
/**
 * 안전한 날짜 파싱 함수
 */
scwin.parseValidDate = function (dateInput) {
    if (!dateInput) {
        return null;
    }

    try {
        let dateString = dateInput.toString().trim();
        if (dateString === "" || dateString === "null" || dateString === "undefined") {
            return null;
        }

        let parsedDate = new Date(dateString);

        // 유효한 날짜인지 확인
        if (isNaN(parsedDate.getTime())) {
            return null;
        }

        return parsedDate;
    } catch (e) {
        return null;
    }
};

scwin.convertToMMDDYYYY = function (dateInput) {
    if (!dateInput) {
        return "";
    }

    try {
        // Date 객체인 경우
        if (dateInput instanceof Date) {
            // 유효한 Date 객체인지 확인
            if (isNaN(dateInput.getTime())) {
                return "";
            }
            let month = (dateInput.getMonth() + 1).toString().padStart(2, '0');
            let day = dateInput.getDate().toString().padStart(2, '0');
            let year = dateInput.getFullYear();
            return month + "/" + day + "/" + year;
        }

        // 문자열인 경우
        let dateString = dateInput.toString();
        if (dateString.trim() === "") {
            return "";
        }

        // yyyy-mm-dd -> mm/dd/yyyy 변환
        let parts = dateString.split("-");
        if (parts.length === 3) {
            let year = parts[0];
            let month = parts[1];
            let day = parts[2];
            return month + "/" + day + "/" + year;
        }
        return dateString;
    } catch (e) {
        return "";
    }
};

/**
 * Date 객체를 mm/dd/yyyy 형식으로 변환
 */
scwin.formatToMMDDYYYY = function (date) {
    let month = (date.getMonth() + 1).toString().padStart(2, '0');
    let day = date.getDate().toString().padStart(2, '0');
    let year = date.getFullYear();
    return month + "/" + day + "/" + year;
};

/**
 * 간트차트 월별 네비게이션 초기화
 */
scwin.initGanttNavigation = function () {
    // 현재 날짜로 동적 초기화
    let currentDate = new Date();
    scwin.currentGanttYear = currentDate.getFullYear();
    scwin.currentGanttMonth = currentDate.getMonth() + 1;

    // 레이블 업데이트
    scwin.updateGanttMonthLabel();

};

/**
 * 간트차트 월 레이블 업데이트
 */
scwin.updateGanttMonthLabel = function () {
    let monthNames = ["1월", "2월", "3월", "4월", "5월", "6월",
        "7월", "8월", "9월", "10월", "11월", "12월"];

    let labelText = scwin.currentGanttYear + "년 " + monthNames[scwin.currentGanttMonth - 1];

    // 레이블 컴포넌트 업데이트
    let monthLabel = $p.getComponentById("lbl_gantt_current_month");
    if (monthLabel) {
        monthLabel.setValue(labelText);
    }

};

/**
 * 이전 월로 이동
 */
scwin.moveToPreviousMonth = function () {
    if (scwin.currentGanttMonth > 1) {
        scwin.currentGanttMonth--;
    } else {
        scwin.currentGanttMonth = 12;
        scwin.currentGanttYear--;
    }


    // 레이블 업데이트
    scwin.updateGanttMonthLabel();

    // 간트차트 새로고침
    scwin.refreshGanttChart();
};

/**
 * 다음 월로 이동
 */
scwin.moveToNextMonth = function () {
    if (scwin.currentGanttMonth < 12) {
        scwin.currentGanttMonth++;
    } else {
        scwin.currentGanttMonth = 1;
        scwin.currentGanttYear++;
    }


    // 레이블 업데이트
    scwin.updateGanttMonthLabel();

    // 간트차트 새로고침
    scwin.refreshGanttChart();
};

/**
 * 간트차트 새로고침 (월 변경 시)
 */
scwin.refreshGanttChart = function () {

    // 전체 scwin.taskList 확인
    if (!scwin.taskList || scwin.taskList.length === 0) {
        return;
    }


    // 전체 taskList를 현재 월 우선으로 정렬 (현재 월 태스크 위쪽, 나머지 아래쪽)

    // 해당 월의 시작일과 종료일 계산
    let monthStart = new Date(scwin.currentGanttYear, scwin.currentGanttMonth - 1, 1);
    let monthEnd = new Date(scwin.currentGanttYear, scwin.currentGanttMonth, 0);

    // 1단계: 모든 태스크를 날짜 상태에 따라 분류
    let tasksWithDateStatus = scwin.taskList.map(function(task) {
        let hasValidDates = task.startDate && task.endDate && 
                           task.startDate.trim() !== "" && task.endDate.trim() !== "";

        let startDate = null;
        let endDate = null;

        if (hasValidDates) {
            startDate = scwin.parseValidDate(task.startDate);
            endDate = scwin.parseValidDate(task.endDate);
            hasValidDates = startDate && endDate; // 파싱도 성공해야 유효
        }

        return {
            task: task,
            hasValidDates: hasValidDates,
            startDate: startDate,
            endDate: endDate
        };
    });


    // 2단계: 현재 월 태스크, 다른 월 태스크, 날짜 없는 태스크로 분리
    let currentMonthTasks = [];
    let otherMonthTasks = [];
    let tasksWithoutDates = [];

    tasksWithDateStatus.forEach(function(item) {
        let task = item.task;

        if (!item.hasValidDates) {
            // 날짜가 없는 태스크는 맨 아래로
            tasksWithoutDates.push(task);
        } else {
            // 현재 월과 겹치는지 확인
            let isOverlapping = item.startDate <= monthEnd && item.endDate >= monthStart;

            if (isOverlapping) {
                currentMonthTasks.push(task);
            } else {
                otherMonthTasks.push(task);
            }
        }
    });

    // 3단계: 각 그룹을 시작날짜 순으로 정렬
    currentMonthTasks.sort(function(a, b) {
        let dateA = scwin.parseValidDate(a.startDate);
        let dateB = scwin.parseValidDate(b.startDate);
        return dateA.getTime() - dateB.getTime();
    });

    otherMonthTasks.sort(function(a, b) {
        let dateA = scwin.parseValidDate(a.startDate);
        let dateB = scwin.parseValidDate(b.startDate);
        return dateA.getTime() - dateB.getTime();
    });

    // 4단계: 우선순위에 따라 배치 (현재 월 → 다른 월 → 날짜 없는 태스크)
    let sortedTaskList = currentMonthTasks.concat(otherMonthTasks).concat(tasksWithoutDates);


    // 간트차트 데이터 리스트를 정렬된 태스크로 구성 (모든 태스크를 row로 표시)
    dlt_gantt_schedule.removeAll();

    for (let i = 0; i < sortedTaskList.length; i++) {
        let task = sortedTaskList[i];

        // 모든 태스크를 간트차트에 추가 (날짜 없는 태스크도 포함하여 정렬 순서 유지)
        let hasValidDates = task.startDate && task.endDate && 
                           task.startDate.trim() !== "" && task.endDate.trim() !== "";

        dlt_gantt_schedule.insertRow(i);
        dlt_gantt_schedule.setCellData(i, "taskId", task.taskId);
        dlt_gantt_schedule.setCellData(i, "taskTitle", task.taskTitle);
        dlt_gantt_schedule.setCellData(i, "startDate", hasValidDates ? task.startDate : ""); // 빈값은 빈 문자열로
        dlt_gantt_schedule.setCellData(i, "endDate", hasValidDates ? task.endDate : "");     // 빈값은 빈 문자열로
        dlt_gantt_schedule.setCellData(i, "boardId", task.boardId);
        dlt_gantt_schedule.setCellData(i, "boardTitle", task.boardTitle || "보드");
        dlt_gantt_schedule.setCellData(i, "priority", task.priority || "MEDIUM");
        dlt_gantt_schedule.setCellData(i, "tags", task.tags || "");
    }


    // 해당 월의 카테고리 업데이트 (그래프는 해당 월 부분만 표시)
    let categoryData = scwin.createMonthlyCategories(scwin.currentGanttYear, scwin.currentGanttMonth);
    if (categoryData) {
        gantt_chart_unique.setCategories(categoryData);
    }

    // 간트차트 다시 그리기 (정렬된 전체 태스크로 호출하되, 카테고리는 해당 월만)
    scwin.loadTasksToGantt(sortedTaskList, scwin.currentGanttYear, scwin.currentGanttMonth);
};

/**
 * 특정 월의 태스크만 필터링
 */
scwin.filterTasksByMonth = function (tasks, year, month) {
    return tasks.filter(function (task) {
        if (!task.startDate && !task.endDate) {
            return false;
        }

        let taskStartDate = new Date(task.startDate);
        let taskEndDate = new Date(task.endDate);

        let monthStart = new Date(year, month - 1, 1);
        let monthEnd = new Date(year, month, 0);

        // 태스크가 해당 월과 겹치는지 확인
        return (taskStartDate <= monthEnd && taskEndDate >= monthStart);
    });
};

/**
 * 칸반 데이터 업데이트 후 간트차트 동기화 함수
 * 현재 간트차트 뷰가 활성화되어 있을 때만 간트차트를 업데이트
 */
scwin.syncGanttWithKanban = function () {

    // 간트차트 뷰가 현재 활성화되어 있는지 확인
    let ganttView = $p.getComponentById("grp_gantt_view");
    if (!ganttView) {
        return;
    }

    // 간트차트 뷰가 보이는 상태인지 안전하게 확인
    try {
        // WebSquare 컴포넌트에서 가시성을 확인하는 안전한 방법들
        let isGanttVisible = false;

        // 방법 1: isVisible() 메소드 시도
        if (typeof ganttView.isVisible === 'function') {
            isGanttVisible = ganttView.isVisible();
        }
        // 방법 2: DOM 스타일 확인
        else if (ganttView.getElement && ganttView.getElement()) {
            let element = ganttView.getElement();
            isGanttVisible = element.style.display !== 'none';
        }
        // 방법 3: 간단히 항상 동기화 (안전한 fallback)
        else {
            isGanttVisible = true;
        }


        if (isGanttVisible) {
            // 간트차트 데이터 로딩
            scwin.loadGanttData();
        } else {
        }
    } catch (error) {
        // 오류 발생 시 안전하게 동기화 수행
        try {
            scwin.loadGanttData();
        } catch (loadError) {
        }
    }
};

/**
 * 간트차트 데이터 로딩 함수
 */
scwin.loadGanttData = function () {

    // 간트차트 데이터 리스트 초기화
    dlt_gantt_schedule.removeAll();

    // 칸반의 태스크 데이터 확인 (여러 소스에서)
    let taskData = null;

    // 1. scwin.taskList에서 확인
    if (scwin.taskList && scwin.taskList.length > 0) {
        taskData = scwin.taskList;
    }
    // 2. dlt_scwin.taskList DataList에서 확인  
    else {
        try {
            let taskListComponent = $p.getComponentById("dlt_scwin.taskList");
            if (taskListComponent) {
                taskData = taskListComponent.getAllJSON();
                // scwin.taskList에도 동기화
                scwin.taskList = taskData || [];
            }
        } catch (e) {
        }
    }

    if (!taskData || taskData.length === 0) {
        taskData = [];
        scwin.taskList = [];
    }

    // 전체 태스크를 현재 월 우선으로 정렬 (현재 월 태스크 위쪽, 나머지 아래쪽)

    // 현재 간트차트 월 정보
    let currentYear = scwin.currentGanttYear || (new Date()).getFullYear();
    let currentMonth = scwin.currentGanttMonth || ((new Date()).getMonth() + 1);

    // 해당 월의 시작일과 종료일 계산
    let monthStart = new Date(currentYear, currentMonth - 1, 1);
    let monthEnd = new Date(currentYear, currentMonth, 0);

    // 1단계: 모든 태스크를 유효/무효로 구분 (제외하지 않음)
    let tasksWithDateStatus = taskData.map(function(task) {
        // 날짜 유효성 검사
        let hasValidDates = false;
        let startDate = null;
        let endDate = null;

        if (task.startDate && task.endDate && 
            task.startDate.trim() !== "" && task.endDate.trim() !== "") {
            startDate = scwin.parseValidDate(task.startDate);
            endDate = scwin.parseValidDate(task.endDate);
            hasValidDates = !!(startDate && endDate);
        }

        if (!hasValidDates) {
        }

        return {
            task: task,
            hasValidDates: hasValidDates,
            startDate: startDate,
            endDate: endDate
        };
    });


    // 2단계: 현재 월 태스크, 다른 월 태스크, 날짜 없는 태스크로 분리
    let currentMonthTasks = [];
    let otherMonthTasks = [];
    let tasksWithoutDates = [];

    tasksWithDateStatus.forEach(function(item) {
        let task = item.task;

        if (!item.hasValidDates) {
            // 날짜가 없는 태스크는 맨 아래로
            tasksWithoutDates.push(task);
        } else {
            // 현재 월과 겹치는지 확인
            let isOverlapping = item.startDate <= monthEnd && item.endDate >= monthStart;

            if (isOverlapping) {
                currentMonthTasks.push(task);
            } else {
                otherMonthTasks.push(task);
            }
        }
    });

    // 3단계: 각 그룹을 시작날짜 순으로 정렬
    currentMonthTasks.sort(function(a, b) {
        let dateA = scwin.parseValidDate(a.startDate);
        let dateB = scwin.parseValidDate(b.startDate);
        return dateA.getTime() - dateB.getTime();
    });

    otherMonthTasks.sort(function(a, b) {
        let dateA = scwin.parseValidDate(a.startDate);
        let dateB = scwin.parseValidDate(b.startDate);
        return dateA.getTime() - dateB.getTime();
    });

    // 4단계: 우선순위에 따라 배치 (현재 월 → 다른 월 → 날짜 없는 태스크)
    taskData = currentMonthTasks.concat(otherMonthTasks).concat(tasksWithoutDates);


    let validTaskIndex = 0;
    for (let i = 0; i < taskData.length; i++) {
        let task = taskData[i];

        // 간트차트 데이터 생성 (날짜 없는 태스크도 포함하여 정렬 순서 유지)
        let hasValidDates = task.startDate && task.endDate && 
                           task.startDate.trim() !== "" && task.endDate.trim() !== "";

        let ganttData = {
            taskId: task.taskId,
            taskTitle: task.taskTitle,
            startDate: hasValidDates ? task.startDate : "", // 빈값은 빈 문자열로 설정
            endDate: hasValidDates ? task.endDate : "",     // 빈값은 빈 문자열로 설정
            boardId: task.boardId,
            boardTitle: task.boardTitle || "보드",
            priority: task.priority || "MEDIUM",
            tags: task.tags || ""
        };


        // 간트차트 데이터 리스트에 추가
        dlt_gantt_schedule.insertRow(validTaskIndex);
        dlt_gantt_schedule.setCellData(validTaskIndex, "taskId", ganttData.taskId);
        dlt_gantt_schedule.setCellData(validTaskIndex, "taskTitle", ganttData.taskTitle);
        dlt_gantt_schedule.setCellData(validTaskIndex, "startDate", ganttData.startDate);
        dlt_gantt_schedule.setCellData(validTaskIndex, "endDate", ganttData.endDate);
        dlt_gantt_schedule.setCellData(validTaskIndex, "boardId", ganttData.boardId);
        dlt_gantt_schedule.setCellData(validTaskIndex, "boardTitle", ganttData.boardTitle);
        dlt_gantt_schedule.setCellData(validTaskIndex, "priority", ganttData.priority);
        dlt_gantt_schedule.setCellData(validTaskIndex, "tags", ganttData.tags);

        validTaskIndex++;
    }


    // 간트차트에 태스크 데이터 표시
    if (validTaskIndex > 0) {
        // 현재 월로 초기화 (월별 네비게이션 기본 설정)
        let currentDate = new Date();
        scwin.currentGanttYear = currentDate.getFullYear();
        scwin.currentGanttMonth = currentDate.getMonth() + 1;
        scwin.updateGanttMonthLabel();

        // 초기 로딩은 전체 데이터로 표시하되, 현재 월 범위만 그리기
        scwin.loadTasksToGantt(taskData, scwin.currentGanttYear, scwin.currentGanttMonth);
    } else {
        // 유효한 태스크가 없어도 계속 진행하여 더미 데이터 생성
        scwin.initGanttNavigation();

        let currentDate = new Date();
        scwin.currentGanttYear = currentDate.getFullYear();
        scwin.currentGanttMonth = currentDate.getMonth() + 1;
        scwin.updateGanttMonthLabel();

        // 빈 배열로 전달하여 더미 데이터 생성
        scwin.loadTasksToGantt([], scwin.currentGanttYear, scwin.currentGanttMonth);
    }
};

/**
 * 날짜 포맷팅 (mm/dd/yyyy)
 */
scwin.formatDate = function (date) {
    let month = (date.getMonth() + 1).toString().padStart(2, '0');
    let day = date.getDate().toString().padStart(2, '0');
    let year = date.getFullYear();
    return month + "/" + day + "/" + year;
};

// GitHub 버튼 클릭 - GitHub App 관리 페이지로 이동
scwin.github_onclick = function (e) {

    // 현재 프로젝트 데이터 확인
    let projectData = scwin.currentProjectData;
    if (!projectData) {
        return;
    }

    // 현재 로그인된 사용자 정보 가져오기
    let currentUserId = null;
    try {
        // 1. 프로젝트 데이터에서 사용자 ID 가져오기 (우선순위 1)
        if (projectData && projectData.userId) {
            currentUserId = projectData.userId;
        }

        // 2. WebSquare 파라미터에서 가져오기
        if (!currentUserId && typeof $p !== "undefined" && $p.getParameter) {
            currentUserId = $p.getParameter("userId") || $p.getParameter("user_id") || $p.getParameter("userEmail");
        }

        // 3. 세션 스토리지에서 가져오기
        if (!currentUserId && typeof sessionStorage !== "undefined") {
            currentUserId = sessionStorage.getItem("userId") || sessionStorage.getItem("userEmail") || sessionStorage.getItem("user_id");
        }

        // 4. 로컬 스토리지에서 가져오기
        if (!currentUserId && typeof localStorage !== "undefined") {
            currentUserId = localStorage.getItem("userId") || localStorage.getItem("userEmail") || localStorage.getItem("user_id");
        }

        // 5. 전역 변수에서 가져오기
        if (!currentUserId && typeof window !== "undefined") {
            currentUserId = window.currentUserId || window.userEmail || window.userId;
        }

        if (currentUserId && currentUserId.trim().length > 0 && currentUserId !== "user01") {
            currentUserId = currentUserId.trim();
        } else {
            return;
        }
    } catch (e) {
        return;
    }


    // 프로젝트 정보를 팝업에 전달
    let jsnPopupData = {
        type: "json",
        name: "project_param",
        data: {
            projectId: projectData.projectId,
            projectName: projectData.projectName,
            description: projectData.description,
            userId: currentUserId
        }
    };

    let options = {
        id: "github_manager_popup",
        type: "wframePopup",
        width: "1000",
        height: "700",
        left: "" + ((window.innerWidth - 1000) / 2) + "",
        top: "100",
        popupName: "GitHub 관리 - " + projectData.projectName,
        modal: true,
        closeAction: "scwin.github_popup_closeAction",
        customTitleBar: false,
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/project/githubManager.xml", options);
};

// GitHub 팝업 닫기 액션
scwin.github_popup_closeAction = function (argRuntimeID, argJsnInfo) {
    let popObj = $p.getPopupWindow(argRuntimeID);
    // GitHub 관련 데이터 새로고침 로직 추가 가능
    return true;
};

// 팝업 닫기 액션
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    let popObj = $p.getPopupWindow(argRuntimeID);
    return true;
};

scwin.add_task_submitdone = function (e) {

    // WebSquare 응답 구조에서 태스크 데이터 추출
    let responseData = e.responseJSON;
    let taskData = responseData.elData;


    if (!taskData || !taskData.taskId) {
        return;
    }

    // 실제 DB에서 받은 데이터로 카드 데이터 구성
    let cardData = {
        taskId: taskData.taskId,
        taskTitle: taskData.taskTitle,
        priority: taskData.priority || "MEDIUM",
        startDate: taskData.startDate || "",
        endDate: taskData.endDate || "",
        tags: taskData.tags || "",
        projectUserId: taskData.projectUserId || "",
        taskDescription: "", // 현재 TaskVo에 없는 필드
        boardId: taskData.boardId // DB에서 받은 실제 boardId 사용
    };


    // 해당 보드의 카드 컨테이너에 카드 동적 생성
    scwin.createKanbanCardInBoard(cardData);

    // 입력 폼 초기화
    dm_taskVo.set("taskTitle", "");
    dm_taskVo.set("boardId", "");
};

/**
 * 해당 보드의 카드 컨테이너에 칸반 카드를 동적 생성하는 함수
 * @param {Object} cardData - 카드 데이터 (taskId, taskTitle, boardId 등)
 */
scwin.createKanbanCardInBoard = function (cardData) {

    if (!cardData.boardId) {
        return;
    }

    // 해당 보드의 카드 컨테이너 찾기
    let cardContainerId = "card_container_" + cardData.boardId;
    let targetContainer = eval(cardContainerId);

    if (!targetContainer) {
        return;
    }


    // 고유한 카드 ID 생성
    let cardId = "card_" + cardData.taskId;

    // 중복 생성 방지 - 이미 존재하는 카드는 생성하지 않음
    let existingCard = $p.getComponentById(cardId);
    if (existingCard) {
        return existingCard;
    }

    // 카드 데이터 디버깅

    // 우선순위 값 정규화 (대소문자 통일 및 기본값 설정)
    let normalizedPriority = "";
    if (cardData.priority && typeof cardData.priority === "string") {
        normalizedPriority = cardData.priority.toUpperCase();
    } else {
        normalizedPriority = "MEDIUM"; // 기본값
    }

    // 우선순위에 따른 CSS 클래스 결정
    let priorityClass = "";
    let priorityText = "";
    if (normalizedPriority === "HIGH") {
        priorityClass = "priority-high";
        priorityText = "높음";
    } else if (normalizedPriority === "MEDIUM") {
        priorityClass = "priority-medium";
        priorityText = "보통";
    } else if (normalizedPriority === "LOW") {
        priorityClass = "priority-low";
        priorityText = "낮음";
    } else {
        priorityClass = "priority-medium"; // 알 수 없는 값은 보통으로 설정
        priorityText = "보통";
    }

    // 1. 메인 카드 그룹 생성 (드래그 가능하도록 설정)
    let cardGroup = null;
    try {
        cardGroup = $p.dynamicCreate(
            cardId,
            "group",
            {
                className: "project-card draggable-card",
                style: "margin-bottom: 8px; padding: 12px; background: white; border: 1px solid #d0d7de; border-radius: 6px; cursor: move;"
            },
            targetContainer
        );
    } catch (error) {
        return;
    }

    if (!cardGroup) {
        return;
    }

    // 생성된 카드에 onclick 이벤트 핸들러를 연결합니다.
    cardGroup.bind("onclick", scwin.new_task_onclick);

    // WebSquare 컴포넌트 렌더링 완료 후 이벤트 바인딩 (async/await 사용)
    scwin.setupDragEventsAsync(cardGroup, cardData, cardId);

    // 2. 카드 헤더 그룹 생성
    let headerGroup = null;
    try {
        headerGroup = $p.dynamicCreate(
            cardId + "_header",
            "group",
            {
                className: "project-card-header",
                style: "display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px;"
            },
            cardGroup
        );
    } catch (error) {
        cardGroup.remove();
        return;
    }

    if (!headerGroup) {
        cardGroup.remove();
        return;
    }

    // 3. 작업 제목 생성
    let titleSpan = null;
    try {
        titleSpan = $p.dynamicCreate(
            cardId + "_title",
            "output",
            {
                className: "project-name",
                style: "font-weight: 500; font-size: 14px; color: #24292f; line-height: 1.3;"
            },
            headerGroup
        );
        if (titleSpan) {
            titleSpan.setValue(cardData.taskTitle);
        }
    } catch (error) {
    }

    // 4. 우선순위 배지 생성
    let prioritySpan = null;
    try {
        prioritySpan = $p.dynamicCreate(
            cardId + "_priority",
            "output",
            {
                className: "priority-badge " + priorityClass
            },
            headerGroup
        );
        if (prioritySpan) {
            prioritySpan.setValue(priorityText);
        }
    } catch (error) {
    }

    // 5. 설명 생성 (있는 경우)
    if (cardData.taskDescription && cardData.taskDescription.trim()) {
        let descSpan = $p.dynamicCreate(
            cardId + "_desc",
            "output",
            {
                className: "project-description",
                style: "font-size: 12px; color: #656d76; line-height: 1.4; margin-bottom: 8px;"
            },
            cardGroup
        );
        if (descSpan) {
            descSpan.setValue(cardData.taskDescription);
        }
    }

    // 6. 메타데이터 그룹 생성
    let metaGroup = $p.dynamicCreate(
        cardId + "_meta",
        "group",
        {
            className: "project-meta",
            style: "display: flex; justify-content: space-between; align-items: center; font-size: 12px; color: #656d76;"
        },
        cardGroup
    );

    // 7. 담당자 정보 (있는 경우)
    if (cardData.projectUserId) {
        let assigneeSpan = $p.dynamicCreate(
            cardId + "_assignee",
            "output",
            {
                className: "assignee-info"
            },
            metaGroup
        );
        if (assigneeSpan) {
            // 서버에서 담당자 우선으로 보내준 userName 사용
            let userName = cardData.userName || scwin.getUserNameByUserId(cardData.projectUserId, cardData);
            assigneeSpan.setValue("담당자: " + userName);
        }
    }

    // 8. 마감일 (있는 경우)
    if (cardData.endDate) {
        let dueDateSpan = $p.dynamicCreate(
            cardId + "_due_date",
            "output",
            {
                className: "due-date"
            },
            metaGroup
        );
        if (dueDateSpan) {
            dueDateSpan.setValue("마감: " + cardData.endDate);
        }
    }


    return cardGroup;
};

/**
 * 칸반 카드를 동적으로 생성하는 함수 (기존 함수 - 호환성 유지)
 * @param {Object} cardData - 카드 데이터 (taskId, taskTitle, priority 등)
 * @param {String} columnType - 컬럼 타입 ("todo", "inprogress", "done")
 */
scwin.createKanbanCard = function (cardData, columnType) {

    // 컬럼별 타겟 컨테이너 ID 매핑 (동적 생성된 컨테이너 사용)
    let containerMap = {
        "todo": "card_container_BOARD_TODO_001",
        "inprogress": "card_container_BOARD_PROGRESS_001",
        "done": "card_container_BOARD_DONE_001"
    };

    // 동적으로 생성된 컨테이너 찾기 (boardId 기반)
    if (cardData.boardId) {
        containerMap[columnType] = "card_container_" + cardData.boardId;
    }

    let containerId = containerMap[columnType];
    if (!containerId) {
        return;
    }

    // 타겟 컨테이너 객체 가져오기
    let targetContainer = eval(containerId);
    if (!targetContainer) {
        return;
    }

    // 우선순위에 따른 CSS 클래스 결정
    let priorityClass = "priority-medium"; // 기본값
    let priorityText = "보통";
    if (cardData.priority === "HIGH") {
        priorityClass = "priority-high";
        priorityText = "높음";
    } else if (cardData.priority === "LOW") {
        priorityClass = "priority-low";
        priorityText = "낮음";
    }

    // 고유한 카드 ID 생성
    let cardId = "card_" + (cardData.taskId || new Date().getTime());

    // 1. 메인 카드 그룹 생성
    let cardGroup = $p.dynamicCreate(
        cardId,
        "group",
        {
            className: "project-card",
            "ev:onclick": "scwin.new_task_onclick",
            "data-task-id": cardData.taskId || "",
            "data-board-id": cardData.boardId || "",
            "data-row": "0"
        },
        targetContainer
    );

    // 2. 카드 헤더 그룹 생성
    let headerGroup = $p.dynamicCreate(
        cardId + "_header",
        "group",
        {
            className: "project-card-header"
        },
        cardGroup
    );

    // 3. 작업 제목 생성
    let titleSpan = $p.dynamicCreate(
        cardId + "_title",
        "output",
        {
            className: "project-name"
        },
        headerGroup
    );
    if (titleSpan) {
        titleSpan.setValue(cardData.taskTitle);
    }

    // 4. 우선순위 배지 생성
    let prioritySpan = $p.dynamicCreate(
        cardId + "_priority",
        "output",
        {
            className: "priority-badge " + priorityClass
        },
        headerGroup
    );
    if (prioritySpan) {
        prioritySpan.setValue(priorityText);
    }

    // 5. 설명 생성 (있는 경우)
    if (cardData.taskDescription) {
        let descSpan = $p.dynamicCreate(
            cardId + "_desc",
            "output",
            {
                className: "project-description"
            },
            cardGroup
        );
        if (descSpan) {
            descSpan.setValue(cardData.taskDescription);
        }
    }

    // 6. 메타데이터 그룹 생성
    let metaGroup = $p.dynamicCreate(
        cardId + "_meta",
        "group",
        {
            className: "project-meta"
        },
        cardGroup
    );
    if (!metaGroup) {
        return;
    }

    // 7. 담당자 정보 그룹 생성
    let assigneeGroup = $p.dynamicCreate(
        cardId + "_assignee",
        "group",
        {
            className: "assignee"
        },
        metaGroup
    );
    if (!assigneeGroup) {
        return;
    }

    // 8. 담당자 아바타 생성
    let avatarSpan = $p.dynamicCreate(
        cardId + "_avatar",
        "output",
        {
            className: "assignee-avatar"
        },
        assigneeGroup
    );
    if (avatarSpan) {
        // 서버에서 담당자 우선으로 보내준 userName 사용
        let userName = cardData.userName || scwin.getUserNameByUserId(cardData.projectUserId, cardData);
        if (userName && typeof userName === 'string' && userName.length > 0) {
            avatarSpan.setValue(userName.charAt(0)); // 사용자 이름의 첫 글자
        } else {
            avatarSpan.setValue('?'); // 기본값
        }
    } else {
    }

    // 9. 담당자 이름 생성
    let assigneeNameSpan = $p.dynamicCreate(
        cardId + "_assignee_name",
        "output",
        {},
        assigneeGroup
    );
    if (assigneeNameSpan) {
        // 서버에서 담당자 우선으로 보내준 userName 사용
        let userName = cardData.userName || scwin.getUserNameByUserId(cardData.projectUserId, cardData);
        if (userName && typeof userName === 'string') {
            assigneeNameSpan.setValue(userName);
        } else {
            assigneeNameSpan.setValue('담당자 없음');
        }
    } else {
    }

    // 10. 마감일 생성 (있는 경우)
    if (cardData.endDate) {
        let dueDateSpan = $p.dynamicCreate(
            cardId + "_due_date",
            "output",
            {
                className: "due-date"
            },
            metaGroup
        );
        if (dueDateSpan && cardData.endDate) {
            dueDateSpan.setValue(cardData.endDate);
        }
    }

    return cardGroup;
};

scwin.load_Board_submitdone = function (e) {

    // 응답에서 보드 데이터 추출
    let responseData = e.responseJSON;
    let boardList = responseData.boardVoList;
    let userHeader = responseData.userHeader;
    dm_userInfo.set("userId", userHeader.userId);
    dm_userInfo.set("userName", userHeader.userName);
    dm_userInfo.set("userImage", userHeader.userImage);
    if (!boardList || boardList.length === 0) {
        return;
    }


    // DataList에 보드 데이터 설정
    dlt_boardListVo.setJSON(boardList);

    // 동적 칸반 컬럼들 생성
    scwin.createDynamicKanbanColumns(boardList);
};

/**
 * 현재 프로젝트 ID를 가져오는 함수
 * 여러 소스에서 프로젝트 ID를 조회하여 반환
 */
scwin.getProjectId = function () {
    let projectId = null;

    // 1. 현재 프로젝트 데이터에서 가져오기
    if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
        projectId = scwin.currentProjectData.projectId;
    }

    // 2. dm_projectVo에서 가져오기
    if (!projectId) {
        try {
            projectId = dm_projectVo.get("projectId");
        } catch (e) {
        }
    }

    // 3. URL 파라미터에서 가져오기
    if (!projectId) {
        try {
            let urlParams = new URLSearchParams(window.location.search);
            projectId = urlParams.get('projectId');
        } catch (e) {
        }
    }

    return projectId;
};

/**
 * 칸반 보드 전체 새로고침 함수
 * 보드 목록과 태스크 목록을 다시 로드하여 칸반 보드를 업데이트
 */
scwin.refreshKanbanBoard = function () {

    try {
        // 1. 보드 목록 재로드
        let projectId = scwin.getProjectId();
        if (!projectId) {
            return;
        }

        // 2. 현재 프로젝트 정보 설정
        dm_projectVo.set("projectId", projectId);

        // 3. 보드 목록 로드 (이것이 완료되면 자동으로 태스크도 로드됨)
        $p.executeSubmission("load_Board");


    } catch (error) {
        throw error;
    }
};

/**
 * 보드 데이터를 기반으로 동적 칸반 컬럼들을 생성하는 함수 (순차 실행)
 * @param {Array} boardList - 서버에서 받은 보드 목록
 */
scwin.createDynamicKanbanColumns = function (boardList) {

    // 새로운 보드 로딩 시작 시 기존 태스크 데이터 초기화
    scwin.taskList = [];

    // boardList 유효성 검증
    if (!boardList || !Array.isArray(boardList) || boardList.length === 0) {
        return;
    }

    let kanbanContainer = grp_kanban_board;
    if (!kanbanContainer) {
        return;
    }

    // 이미 생성 중인 경우 중복 실행 방지
    if (scwin.isCreatingColumns) {
        return;
    }

    scwin.isCreatingColumns = true;

    scwin.clearExistingKanbanColumns();

    // 1. 모든 컬럼을 먼저 생성
    let validBoardIds = [];
    for (let i = 0; i < boardList.length; i++) {
        const board = boardList[i];

        // board 객체 유효성 검증
        if (!board || !board.boardId || !board.boardTitle) {
            continue;
        }


        try {
            scwin.createSingleKanbanColumn(board, i, kanbanContainer);
            validBoardIds.push(board.boardId); // 유효한 보드 ID 수집
        } catch (error) {
            continue;
        }
    }


    // 2. 모든 보드의 태스크를 한 번에 배치 로드 ������
    if (validBoardIds.length > 0) {
        scwin.loadAllBoardTasks(validBoardIds);
    } else {
    }

    // 생성 완료 후 플래그 해제
    setTimeout(function () {
        scwin.isCreatingColumns = false;
    }, 100);
};

/**
 * 태스크 로드 완료 후, 칸반 카드를 생성하는 콜백 함수 (프론트엔드 필터링 지원)
 */
scwin.load_Tasks_submitdone = function (e) {

    // 1. 응답에서 직접 태스크 목록 추출
    let responseData = e.responseJSON;

    // 다중 보드 데이터 누적을 위해 기존 데이터에 추가
    let newTasks = responseData.elData.taskVoList || [];
    if (!scwin.taskList) {
        scwin.taskList = [];
    }
    scwin.taskList = scwin.taskList.concat(newTasks);

    // 칸반 보드용 태스크 처리
    if (scwin.taskList && scwin.taskList.length > 0) {
        let boardId = scwin.taskList[0].boardId; // 첫 번째 태스크의 boardId를 사용

        // 전체 태스크 데이터를 로컬에 저장 (필터링용)
        scwin.storeAllTasksData(boardId, scwin.taskList);

        // 필터링과 정렬을 모두 적용하여 태스크 표시
        scwin.sortAndFilterBoardTasks(boardId);

    } else {

        // boardId 추출 (검색 조건에서)
        let searchCondition = $p.getComponentById("dm_search_task");
        if (searchCondition) {
            let boardId = searchCondition.get("boardId");
            if (boardId) {
                // 빈 데이터 저장 및 정렬/필터링 적용
                scwin.storeAllTasksData(boardId, []);
                scwin.sortAndFilterBoardTasks(boardId);
            }
        }
    }

    // 칸반 데이터 업데이트 후 간트차트 동기화
    scwin.syncGanttWithKanban();
};

/**
 * 기존 동적 칸반 컬럼들을 제거하는 함수 (중복 생성 방지)
 */
scwin.clearExistingKanbanColumns = function () {

    let kanbanContainer = grp_kanban_board;
    if (!kanbanContainer) {
        return;
    }

    // 기존 보드 데이터가 있으면 해당 컬럼들 제거
    let existingBoardList = dlt_boardListVo.getAllJSON();
    if (existingBoardList && existingBoardList.length > 0) {
        for (let i = 0; i < existingBoardList.length; i++) {
            let board = existingBoardList[i];
            let columnId = "grp_dynamic_" + board.boardId;

            try {
                let existingColumn = eval(columnId);
                if (existingColumn) {
                    existingColumn.remove();
                }
            } catch (e) {
            }
        }
    }

    // WebSquare ID로 생성된 동적 컴포넌트들도 확인 제거
    try {
        let children = kanbanContainer.getChildren();
        for (let i = children.length - 1; i >= 0; i--) {
            let child = children[i];
            let childId = child.getID();

            // grp_dynamic_ 또는 card_container_로 시작하는 동적 컴포넌트 제거
            if (childId && (childId.startsWith("grp_dynamic_") || childId.startsWith("card_container_"))) {
                child.remove();
            }
        }
    } catch (e) {
    }

};

/**
 * sleep 유틸리티 함수
 * @param {Number} ms - 대기 시간 (밀리초)
 */
scwin.sleep = function (ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
};

/**
 * 단일 칸반 컬럼을 생성하는 함수
 * @param {Object} board - 보드 데이터 (boardId, boardTitle, projectId)
 * @param {Number} index - 컬럼 순서
 * @param {Object} container - 부모 컨테이너
 */
scwin.createSingleKanbanColumn = function (board, index, container) {
    // board 파라미터 유효성 검증
    if (!board || !board.boardId || !board.boardTitle) {
        return;
    }


    let columnId = "grp_dynamic_" + board.boardId;
    let cardContainerId = "card_container_" + board.boardId;

    // 중복 생성 방지 - 이미 존재하는 컬럼인지 확인
    try {
        let existingColumn = eval(columnId);
        if (existingColumn) {
            return;
        }
    } catch (e) {
        // 컴포넌트가 존재하지 않음 - 정상적으로 생성 진행
    }

    // 1. 메인 컬럼 그룹 생성
    let columnGroup = $p.dynamicCreate(
        columnId,
        "group",
        {
            className: "kanban-column",
            style: "flex: 0 0 300px; margin: 0 8px; background: #f6f8fa; border-radius: 8px; padding: 16px;",
            "data-board-id": board.boardId
        },
        container
    );

    if (!columnGroup) {
        return;
    }

    // 2. 컬럼 헤더 생성
    let headerGroup = $p.dynamicCreate(
        columnId + "_header",
        "group",
        {
            className: "kanban-column-header",
            style: "display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px;"
        },
        columnGroup
    );

    if (!headerGroup) {
        return;
    }

    // 3. 컬럼 제목 그룹 생성
    let titleGroup = $p.dynamicCreate(
        columnId + "_title_group",
        "group",
        {
            style: "display: flex; align-items: center; gap: 8px;"
        },
        headerGroup
    );
    if (!titleGroup) {
        return;
    }

    // 4. 상태 인디케이터 생성
    let statusColor = scwin.getBoardStatusColor(
        (board.boardTitle && typeof board.boardTitle === 'string') ? board.boardTitle : 'default'
    );
    let statusIndicator = $p.dynamicCreate(
        columnId + "_status",
        "output",
        {
            className: "status-indicator",
            style: "width: 8px; height: 8px; border-radius: 50%; background-color: " + statusColor + ";"
        },
        titleGroup
    );
    if (!statusIndicator) {
    }

    // 5. 컬럼 제목 생성
    let titleSpan = $p.dynamicCreate(
        columnId + "_title",
        "output",
        {
            className: "column-title",
            style: "font-weight: 600; font-size: 14px; color: #24292f;"
        },
        titleGroup
    );
    if (titleSpan) {
        try {
            titleSpan.setValue(board.boardTitle || 'Untitled');
        } catch (e) {
        }
    } else {
    }

    // 6. 태스크 카운트 생성 (제거됨)

    // 7. 보드 액션 버튼 그룹 생성 (헤더 우측)
    let actionGroup = $p.dynamicCreate(
        columnId + "_action_group",
        "group",
        {
            style: "display: flex; align-items: center; gap: 4px;"
        },
        headerGroup
    );
    if (!actionGroup) {
    }

    // 8. 보드 삭제 버튼 생성
    let deleteButton = $p.dynamicCreate(
        columnId + "_delete_btn",
        "trigger",
        {
            className: "btn-board-delete",
            style: "width: 24px; height: 24px; padding: 4px; background: transparent; border: none; border-radius: 4px; color: #656d76; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 12px;",
            title: "보드 삭제"
        },
        actionGroup
    );

    if (deleteButton) {
        try {
            deleteButton.setValue("✕"); // X 표시

            // boardId와 boardTitle 저장
            deleteButton.boardId = board.boardId;
            deleteButton.boardTitle = board.boardTitle;
            // 클릭 이벤트 바인딩
            deleteButton.bind("onclick", function(e) {
                scwin.confirmAndDeleteBoard(deleteButton.boardId, deleteButton.boardTitle);
            });

        } catch (e) {
        }
    } else {
    }

    // 9. 카드 컨테이너 생성 (드롭 존으로 설정)
    let cardContainer = $p.dynamicCreate(
        cardContainerId,
        "group",
        {
            className: "kanban-cards-container drop-zone",
            style: "display: flex; flex-direction: column; gap: 8px; min-height: 100px; width: 100%;",
            "data-board-id": board.boardId
        },
        columnGroup
    );

    if (!cardContainer) {
        return;
    }

    // 드롭 존 이벤트 핸들러 추가 (async/await 사용)
    scwin.setupDropZoneAsync(cardContainer, board.boardId, cardContainerId);

    // 10. 카드 추가 버튼 생성
    let addButton = $p.dynamicCreate(
        columnId + "_add_btn",
        "trigger",
        {
            style: "width: 100%; padding: 8px; margin-top: 8px; background: transparent; border: 1px dashed #d1d9e0; border-radius: 6px; color: #656d76; font-size: 14px; cursor: pointer;",
            className: "add-card-btn"
        },
        columnGroup
    );

    if (addButton) {
        // setValue로 버튜 텍스트 설정
        try {
            addButton.setValue("+ 카드 추가");
        } catch (e) {
        }

        // boardId 저장 (null 체크)
        if (board.boardId) {
            addButton.boardId = board.boardId;

            // onclick 이벤트 바인딩
            addButton.bind("onclick", function (e) {
                scwin.dynamicAddCard_onclick_fixed(addButton.boardId);
            });
        } else {
        }

    } else {
    }

};

// ==================== 드래그 락 시스템 ====================

/**
 * 카드 락 요청
 */
scwin.requestCardLock = function (taskId) {
    let currentUserId = scwin.getCurrentUserId();
    let currentUserName = scwin.getCurrentUserName();


    // 이미 다른 사용자가 락을 보유하고 있는지 확인
    if (scwin.lockedCards.has(taskId)) {
        let lockInfo = scwin.lockedCards.get(taskId);
        if (lockInfo.userId !== currentUserId) {
            return false;
        }
    }

    // 락 정보 설정
    let lockInfo = {
        userId: currentUserId,
        userName: currentUserName,
        timestamp: Date.now()
    };

    scwin.lockedCards.set(taskId, lockInfo);
    scwin.myLockedCards.add(taskId);

    // WebSocket으로 락 상태 전파
    scwin.sendCardLockMessage(taskId, "LOCK");

    // 락된 카드에 시각적 표시 추가
    scwin.updateCardLockVisual(taskId, lockInfo);

    return true;
};

/**
 * 카드 락 해제 (편집용)
 */
scwin.releaseCardLock = function (taskId, isAutoRelease) {
    let currentUserId = scwin.getCurrentUserId();


    // 내가 락한 카드인지 확인
    if (!scwin.myLockedCards.has(taskId)) {
        return false;
    }

    // 락 정보 제거
    scwin.lockedCards.delete(taskId);
    scwin.myLockedCards.delete(taskId);

    // WebSocket으로 락 해제 상태 전파
    scwin.sendCardLockMessage(taskId, "UNLOCK");

    // 락 시각적 표시 제거
    scwin.updateCardLockVisual(taskId, null);

    return true;
};

/**
 * 카드 이동 락 요청 (신규)
 */
scwin.requestCardMoveLock = function (taskId) {
    let currentUserId = scwin.getCurrentUserId();
    let currentUserName = scwin.getCurrentUserName();


    // 이미 다른 사용자가 락을 보유하고 있는지 확인
    if (scwin.lockedCards.has(taskId)) {
        let lockInfo = scwin.lockedCards.get(taskId);
        if (lockInfo.userId !== currentUserId) {
            return false;
        }
    }

    // 이동 락 정보 설정
    let moveLockInfo = {
        userId: currentUserId,
        userName: currentUserName,
        timestamp: Date.now(),
        type: "move"
    };

    scwin.lockedCards.set(taskId, moveLockInfo);
    scwin.myLockedCards.add(taskId);

    // WebSocket으로 이동 락 상태 전파
    scwin.sendCardMoveLockMessage(taskId, "MOVE_LOCK");

    // 락된 카드에 시각적 표시 추가
    scwin.updateCardMoveLockVisual(taskId, moveLockInfo);

    return true;
};

/**
 * 카드 이동 락 해제
 */
scwin.releaseCardMoveLock = function (taskId, isAutoRelease) {
    let currentUserId = scwin.getCurrentUserId();


    // 내가 락한 카드인지 확인
    if (!scwin.myLockedCards.has(taskId)) {
        return false;
    }

    // 현재 락이 이동 락인지 확인
    let currentLock = scwin.lockedCards.get(taskId);
    if (!currentLock || currentLock.type !== "move" || currentLock.userId !== currentUserId) {
        return false;
    }

    // 락 정보 제거
    scwin.lockedCards.delete(taskId);
    scwin.myLockedCards.delete(taskId);

    // WebSocket으로 이동 락 해제 상태 전파
    scwin.sendCardMoveLockMessage(taskId, "MOVE_UNLOCK");

    // 락 시각적 표시 제거
    scwin.updateCardMoveLockVisual(taskId, null);

    return true;
};

/**
 * 카드가 락되어 있는지 확인
 */
scwin.isCardLocked = function (taskId) {
    let currentUserId = scwin.getCurrentUserId();

    if (!scwin.lockedCards.has(taskId)) {
        return false;
    }

    let lockInfo = scwin.lockedCards.get(taskId);
    // 내가 락한 카드는 락되지 않은 것으로 처리
    return lockInfo.userId !== currentUserId;
};

/**
 * 카드 락 WebSocket 메시지 전송
 */
scwin.sendCardLockMessage = function (taskId, action) {
    let currentUserId = scwin.getCurrentUserId();
    let currentUserName = scwin.getCurrentUserName();
    let projectId = $p.parent().dm_projectVo.get("projectId");

    let message = {
        type: "CARD_LOCK",
        taskId: taskId,
        userId: currentUserId,
        projectId: projectId,
        message: action + "|" + currentUserName, // "LOCK|사용자명" 또는 "UNLOCK|사용자명"
        timestamp: Date.now()
    };

    scwin.sendWebSocketMessage(message);
};

/**
 * 카드 이동 락 WebSocket 메시지 전송
 */
scwin.sendCardMoveLockMessage = function (taskId, action) {
    let currentUserId = scwin.getCurrentUserId();
    let currentUserName = scwin.getCurrentUserName();
    let projectId = $p.parent().dm_projectVo.get("projectId");

    let message = {
        type: "CARD_LOCK",
        taskId: taskId,
        userId: currentUserId,
        projectId: projectId,
        message: action + "|" + currentUserName, // "MOVE_LOCK|사용자명" 또는 "MOVE_UNLOCK|사용자명"
        timestamp: Date.now()
    };

    scwin.sendWebSocketMessage(message);
};

/**
 * 카드 락 시각적 표시 업데이트
 */
scwin.updateCardLockVisual = function (taskId, lockInfo) {
    try {
        let cardElement = document.querySelector('[data-task-id="' + taskId + '"]');
        if (!cardElement) {
            return;
        }

        if (lockInfo) {
            // 편집 락 표시 추가 - 빨간 테두리와 툴팁
            cardElement.classList.add("card-locked");
            cardElement.title = lockInfo.userName + "님이 편집 중입니다";
            cardElement.setAttribute("data-locked-by", lockInfo.userName);
        } else {
            // 편집 락 표시 제거
            cardElement.classList.remove("card-locked");
            cardElement.removeAttribute("title");
            cardElement.removeAttribute("data-locked-by");
        }
    } catch (e) {
    }
};

/**
 * 카드 이동 락 시각적 표시 업데이트
 */
scwin.updateCardMoveLockVisual = function (taskId, lockInfo) {
    try {
        let cardElement = document.querySelector('[data-task-id="' + taskId + '"]');
        if (!cardElement) {
            return;
        }

        if (lockInfo) {
            // 이동 락 표시 추가 - 주황색 테두리와 툴팁
            cardElement.classList.add("card-move-locked");
            cardElement.title = lockInfo.userName + "님이 이동 중입니다";
            cardElement.setAttribute("data-move-locked-by", lockInfo.userName);

            // 드래그 비활성화
            cardElement.setAttribute("draggable", "false");

        } else {
            // 이동 락 표시 제거
            cardElement.classList.remove("card-move-locked");
            cardElement.removeAttribute("title");
            cardElement.removeAttribute("data-move-locked-by");

            // 드래그 다시 활성화
            cardElement.setAttribute("draggable", "true");

        }
    } catch (e) {
    }
};

/**
 * 다른 사용자의 카드 락 메시지 처리
 */
scwin.handleCardLockMessage = function (message) {

    let currentUserId = scwin.getCurrentUserId();

    // message 필드에서 액션과 사용자명 파싱 ("LOCK|사용자명", "UNLOCK|사용자명", "MOVE_LOCK|사용자명", "MOVE_UNLOCK|사용자명")
    let messageParts = message.message ? message.message.split("|") : [];
    let action = messageParts[0];
    let userName = messageParts[1] || message.userId;

    if (action === "LOCK") {
        // 편집용 락킹
        let lockInfo = {
            userId: message.userId,
            userName: userName,
            timestamp: message.timestamp,
            type: "edit"
        };

        scwin.lockedCards.set(message.taskId, lockInfo);
        scwin.updateCardLockVisual(message.taskId, lockInfo);


    } else if (action === "UNLOCK") {
        // 편집용 언락 
        scwin.lockedCards.delete(message.taskId);
        scwin.updateCardLockVisual(message.taskId, null);


    } else if (action === "MOVE_LOCK") {
        //이동용 락킹 (신규 로직)
        let moveLockInfo = {
            userId: message.userId,
            userName: userName,
            timestamp: message.timestamp,
            type: "move"
        };

        scwin.lockedCards.set(message.taskId, moveLockInfo);
        scwin.updateCardMoveLockVisual(message.taskId, moveLockInfo);


    } else if (action === "MOVE_UNLOCK") {
        //이동용 언락 (신규 로직)
        let currentLock = scwin.lockedCards.get(message.taskId);

        // 이동 락만 해제 (편집 락은 유지)
        if (currentLock && currentLock.type === "move") {
            scwin.lockedCards.delete(message.taskId);
            scwin.updateCardMoveLockVisual(message.taskId, null);
        }
    }
};

// 드래그 시작 시 호출되는 함수
scwin.handleDragStart = function (e) {

    // 드래그되는 카드 정보 저장
    let cardElement = e.target;
    let taskId = cardElement.getAttribute("data-task-id");
    let currentBoardId = cardElement.getAttribute("data-board-id");


    // 필수 정보 유효성 검사
    if (!taskId || !currentBoardId) {
        e.preventDefault();
        return false;
    }

    // 카드 락 확인 - 다른 사용자가 편집하거나 이동 중인지 체크
    if (scwin.isCardLocked(taskId)) {
        let lockInfo = scwin.lockedCards.get(taskId);
        let lockType = lockInfo.type === "move" ? "이동" : "편집";
        $c.win.alert(lockInfo.userName + "님이 현재 이 카드를 " + lockType + " 중입니다. 잠시 후 다시 시도해주세요.");
        e.preventDefault();
        return false;
    }

    //카드 이동 락 요청 (편집 락 대신 이동 락 사용)
    if (!scwin.requestCardMoveLock(taskId)) {
        e.preventDefault();
        return false;
    }

    // 전역 변수에 드래그 정보 저장
    scwin.draggedCard = {
        element: cardElement,
        taskId: taskId,
        sourceBoardId: currentBoardId,
        sourceContainer: cardElement.parentElement,
        timestamp: new Date().getTime() // 타임스탬프 추가로 신뢰성 향상
    };

    // dataTransfer에도 백업 정보 저장
    if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("text/html", cardElement.outerHTML);
        e.dataTransfer.setData("application/json", JSON.stringify({
            taskId: taskId,
            sourceBoardId: currentBoardId
        }));
    } else {
    }

    // 드래그 중 카드 스타일 변경
    cardElement.classList.add("dragging");

    // 전체 화면에 드래그 상태 클래스 추가
    document.body.classList.add("dragging-in-progress");

};

// 드래그 종료 시 호출되는 함수
scwin.handleDragEnd = function (e) {

    // 드래그 스타일 원복
    e.target.classList.remove("dragging");

    // 전체 화면 드래그 상태 클래스 제거
    document.body.classList.remove("dragging-in-progress");

    // 모든 드롭 존의 하이라이트 제거
    let dropZones = document.querySelectorAll(".drop-zone");
    dropZones.forEach(function (zone) {
        zone.classList.remove("drag-over");
    });

    // 드래그가 끝났으므로 카드 이동 락 해제
    if (scwin.draggedCard && scwin.draggedCard.taskId) {
        scwin.releaseCardMoveLock(scwin.draggedCard.taskId, false);
    }
};

// 드래그 상태 정리 함수
scwin.cleanupDragState = function () {

    // 드래그 중인 모든 요소에서 스타일 제거
    let draggingElements = document.querySelectorAll('.dragging');
    draggingElements.forEach(function (element) {
        element.classList.remove("dragging");
    });

    // 전체 드래그 상태 정리
    document.body.classList.remove("dragging-in-progress");

    // 모든 드롭 존의 하이라이트 제거
    let dropZones = document.querySelectorAll(".drop-zone, [data-drop-zone]");
    dropZones.forEach(function (zone) {
        zone.classList.remove("drag-over");
    });

    // 드래그 정보 초기화 (약간의 지연 후)
    setTimeout(function () {
        scwin.draggedCard = null;
    }, 100);
};

// 드래그 오버 이벤트 (드롭 존에서 발생)
scwin.handleDragOver = function (e) {

    // 강력한 기본 동작 방지
    if (e.preventDefault) {
        e.preventDefault();
    }
    if (e.stopPropagation) {
        e.stopPropagation();
    }

    // dataTransfer 설정
    if (e.dataTransfer) {
        e.dataTransfer.dropEffect = "move";
    }

    // 드롭 존 하이라이트
    if (e.currentTarget && e.currentTarget.classList) {
        e.currentTarget.classList.add("drag-over");
    }

    return false; // 추가 방지
};

// 드래그 엔터 이벤트 (드롭 존에 진입)
scwin.handleDragEnter = function (e) {
    e.preventDefault();
    e.stopPropagation();
    e.currentTarget.classList.add("drag-over");
    return false;
};

// 드래그 리브 이벤트 (드롭 존에서 벗어남)
scwin.handleDragLeave = function (e) {
    e.currentTarget.classList.remove("drag-over");
};


// 드롭 이벤트 (실제 드롭 처리)
scwin.handleDrop = function (e) {

    e.preventDefault();
    e.stopPropagation();

    let dropZone = e.currentTarget;
    let targetBoardId = dropZone.getAttribute("data-board-id");


    // 드래그된 카드 정보 확인 (더 안전한 방식)
    if (!scwin.draggedCard || !scwin.draggedCard.element || !scwin.draggedCard.taskId) {

        // 1차 복구 시도: dataTransfer에서 정보 복구
        try {
            let transferData = e.dataTransfer.getData("application/json");
            if (transferData) {
                let dragInfo = JSON.parse(transferData);

                // DOM에서 해당 카드 찾기
                let cardElement = document.querySelector('[data-task-id="' + dragInfo.taskId + '"]');
                if (cardElement) {
                    scwin.draggedCard = {
                        element: cardElement,
                        taskId: dragInfo.taskId,
                        sourceBoardId: dragInfo.sourceBoardId,
                        sourceContainer: cardElement.parentElement
                    };
                }
            }
        } catch (error) {
        }

        // 2차 복구 시도: 드래그 중인 요소에서 정보 복구
        if (!scwin.draggedCard || !scwin.draggedCard.taskId) {
            let draggedElements = document.querySelectorAll('.dragging');
            if (draggedElements.length > 0) {
                let draggedElement = draggedElements[0];
                let taskId = draggedElement.getAttribute("data-task-id");
                let sourceBoardId = draggedElement.getAttribute("data-board-id");

                if (taskId && sourceBoardId) {
                    scwin.draggedCard = {
                        element: draggedElement,
                        taskId: taskId,
                        sourceBoardId: sourceBoardId,
                        sourceContainer: draggedElement.parentElement
                    };
                }
            }
        }

        // 최종 확인: 여전히 정보가 없으면 알림
        if (!scwin.draggedCard || !scwin.draggedCard.taskId) {
            $c.win.alert("드래그된 카드 정보가 없습니다. 다시 시도해주세요.");
            scwin.cleanupDragState();
            return;
        }
    }

    let draggedElement = scwin.draggedCard.element;
    let sourceBoardId = scwin.draggedCard.sourceBoardId;
    let taskId = scwin.draggedCard.taskId;

    // 같은 보드로 이동하는 경우 무시
    if (sourceBoardId === targetBoardId) {
        dropZone.classList.remove("drag-over");
        scwin.cleanupDragState();
        return;
    }

    // 카드 이동 처리
    try {
        scwin.moveCardToBoard(draggedElement, targetBoardId, taskId);

        // WebSocket으로 카드 이동 메시지 전송
        scwin.sendCardMoveMessage(taskId, sourceBoardId, targetBoardId);


    } catch (error) {
    }

    // 드롭 존 하이라이트 제거
    dropZone.classList.remove("drag-over");

    // 드래그 상태 정리
    scwin.cleanupDragState();
};

// 드래그 이벤트 설정
scwin.setupDragEventsAsync = function (cardGroup, cardData, cardId) {

    try {
        // 컴포넌트 직접 처리
        const elementOrComponent = cardGroup;
        // 실제 DOM 요소 찾기 (WebSquare 컴포넌트 대응)
        let targetElement = null;

        if (elementOrComponent && elementOrComponent.element && elementOrComponent.element.nodeType === 1) {
            // 정상적인 DOM 요소가 있는 경우
            targetElement = elementOrComponent.element;
        } else if (elementOrComponent && elementOrComponent.nodeType === 1) {
            // 이미 DOM 요소인 경우
            targetElement = elementOrComponent;
        } else if (elementOrComponent && elementOrComponent.id) {
            // WebSquare 컴포넌트인 경우 - DOM에서 직접 찾기
            targetElement = document.getElementById(elementOrComponent.id);
            if (!targetElement) {
                // ID로 찾지 못한 경우 querySelector로 시도
                targetElement = document.querySelector(`[id="${elementOrComponent.id}"]`);
            }
        }

        if (!targetElement) {
            return;
        }

        // 속성 설정
        targetElement.setAttribute("data-task-id", cardData.taskId);
        targetElement.setAttribute("data-board-id", cardData.boardId);
        targetElement.setAttribute("draggable", "true");


        // 드래그 이벤트 핸들러 바인딩
        targetElement.ondragstart = function (e) {
            scwin.handleDragStart(e);
        };

        targetElement.ondragend = function (e) {
            scwin.handleDragEnd(e);
        };




    } catch (error) {
    }

};


// 드롭 존 설정
scwin.setupDropZoneAsync = function (cardContainer, boardId, cardContainerId) {

    try {
        // 컴포넌트 직접 처리
        const elementOrComponent = cardContainer;


        // DOM 요소가 있는 경우와 없는 경우 처리
        let targetElement = elementOrComponent;
        if (elementOrComponent && elementOrComponent.element) {
            targetElement = elementOrComponent.element;
        } else if (elementOrComponent && elementOrComponent.render && elementOrComponent.render.nodeType === 1) {
            // WebSquare 컴포넌트의 render 속성 사용
            targetElement = elementOrComponent.render;
        } else if (elementOrComponent && elementOrComponent.nodeType === 1) {
            targetElement = elementOrComponent;
        } else if (elementOrComponent && elementOrComponent.id) {
            // ID로 직접 찾기
            targetElement = document.getElementById(elementOrComponent.id);
        } else {
            return;
        }


        // 드롭 존 이벤트 핸들러 바인딩 (WebSquare 호환성을 위해 혼합 방식 사용)

        // 1. dragover 이벤트 - 다중 바인딩 방식
        let dragoverHandler = function (e) {

            // 강력한 기본 동작 방지
            if (e.preventDefault) {
                e.preventDefault();
            }
            if (e.stopPropagation) {
                e.stopPropagation();
            }

            // dataTransfer 설정
            if (e.dataTransfer) {
                e.dataTransfer.dropEffect = "move";
            }

            // 비주얼 피드백
            if (e.currentTarget && e.currentTarget.classList) {
                e.currentTarget.classList.add("drag-over");
            }

            return false;
        };

        // addEventListener 방식
        targetElement.addEventListener('dragover', dragoverHandler, false);

        // 직접 속성 설정 방식
        targetElement.ondragover = dragoverHandler;

        // 캡처 단계 리스너
        targetElement.addEventListener('dragover', dragoverHandler, true);

        // 2. 드롭 이벤트 - 다중 바인딩 방식
        let dropHandler = function (e) {

            e.preventDefault();
            e.stopPropagation();

            // 즉시 실행과 지연 실행 둘 다 시도
            try {
                scwin.handleDrop(e);
            } catch (error) {

                // 지연 실행 시도
                setTimeout(function () {
                    try {
                        scwin.handleDrop(e);
                    } catch (delayedError) {
                    }
                }, 10);
            }
            return false;
        };

        // addEventListener 방식
        targetElement.addEventListener('drop', dropHandler);

        // 직접 속성 설정 방식 (WebSquare 호환성)
        targetElement.ondrop = dropHandler;

        // 3. dragenter 이벤트 - 다중 바인딩 방식
        let dragenterHandler = function (e) {
            e.preventDefault();
            e.stopPropagation();
            if (e.currentTarget && e.currentTarget.classList) {
                e.currentTarget.classList.add("drag-over");
            }
            return false;
        };

        targetElement.addEventListener('dragenter', dragenterHandler, false);
        targetElement.ondragenter = dragenterHandler;
        targetElement.addEventListener('dragenter', dragenterHandler, true);

        // 4. dragleave 이벤트
        let dragleaveHandler = function (e) {
            if (e.currentTarget && e.currentTarget.classList) {
                e.currentTarget.classList.remove("drag-over");
            }
        };

        targetElement.addEventListener('dragleave', dragleaveHandler, false);
        targetElement.ondragleave = dragleaveHandler;


        // WebSquare 환경 전용 설정
        targetElement.setAttribute("data-drop-zone", "true");
        targetElement.setAttribute("data-board-id", boardId);

        // 강제로 드롭 존 CSS 스타일 적용
        targetElement.style.pointerEvents = "auto";

        // 직접 HTML 속성으로 이벤트 핸들러 설정 (WebSquare 호환)
        targetElement.setAttribute("ondragover", "event.preventDefault(); event.dataTransfer.dropEffect='move'; return false;");
        targetElement.setAttribute("ondrop", "event.preventDefault(); scwin.handleDrop(event); return false;");

        targetElement.setAttribute("data-drop-handler", "ready");

        // 강제 이벤트 캡처 설정 (WebSquare 호환성)
        targetElement.addEventListener('drop', dropHandler, true); // 캡처 단계

        // 추가적인 드롭 이벤트 감지 방법 (WebSquare 환경 대응)
        targetElement.setAttribute('onDrop', 'scwin.handleDrop(event)');

        // 전역 이벤트 리스너로 백업 (최후 수단)
        if (!window.globalDropBackup) {
            window.globalDropBackup = true;
            document.addEventListener('drop', function (e) {

                let dropZone = e.target.closest('[data-drop-zone="true"]');

                if (dropZone) {
                    let targetBoardId = dropZone.getAttribute('data-board-id');

                    // 속성 값이 없어도 진행 (디버깅용)
                    if (targetBoardId || true) {
                        e.preventDefault();
                        e.stopPropagation();

                        if (typeof scwin.handleDrop === 'function') {
                            // 이벤트 객체 수정
                            let modifiedEvent = {
                                preventDefault: function () { if (e.preventDefault) e.preventDefault(); },
                                stopPropagation: function () { if (e.stopPropagation) e.stopPropagation(); },
                                currentTarget: dropZone,
                                target: e.target,
                                type: 'drop',
                                dataTransfer: e.dataTransfer
                            };
                            scwin.handleDrop(modifiedEvent);
                        } else {
                        }
                    } else {
                    }
                } else {
                }
            }, true);
        }
        targetElement.addEventListener('drop', dropHandler, true); // 캡처 단계에서도 리스너 추가

    } catch (error) {
    }

};

// 카드를 다른 보드로 이동하는 함수
scwin.moveCardToBoard = function (cardElement, targetBoardId, taskId) {

    try {
        // taskId 검증 및 복구 시도
        if (!taskId || taskId === "" || taskId === "null" || taskId === "undefined") {

            // 카드 element에서 taskId 다시 추출 시도
            taskId = cardElement.getAttribute("data-task-id");

            if (!taskId || taskId === "" || taskId === "null" || taskId === "undefined") {
                $c.win.alert("카드 정보를 찾을 수 없어 이동할 수 없습니다.");
                return false;
            }

        }

        // 현재 보드 정보
        let sourceBoardId = cardElement.getAttribute("data-board-id");

        // 같은 보드로 이동하는 경우 처리하지 않음
        if (sourceBoardId === targetBoardId) {
            return true;
        }

        // 타겟 컴포넌트 찾기
        let targetContainerId = "card_container_" + targetBoardId;

        // WebSquare 컴포넌트 찾기
        let targetContainer = eval(targetContainerId);
        if (!targetContainer) {
            return false;
        }


        // WebSquare 컴포넌트의 DOM 요소 찾기
        let targetDOMElement = null;
        if (targetContainer.element && targetContainer.element.nodeType === 1) {
            targetDOMElement = targetContainer.element;
        } else if (targetContainer.render && targetContainer.render.nodeType === 1) {
            targetDOMElement = targetContainer.render;
        } else {
            // ID로 직접 찾기
            targetDOMElement = document.getElementById(targetContainerId);
        }

        if (!targetDOMElement) {
            return false;
        }


        // 서버에 먼저 업데이트 요청
        dm_taskVo.set("taskId", taskId);
        dm_taskVo.set("boardId", targetBoardId);

        // 비동기 서버 업데이트를 위한 콜백 설정
        scwin.pendingCardMove = {
            cardElement: cardElement,
            sourceBoardId: sourceBoardId,
            targetBoardId: targetBoardId,
            targetDOMElement: targetDOMElement,
            taskId: taskId
        };

        // 서버 업데이트 실행
        $c.sbm.execute(update_task_board);

        return true;

    } catch (error) {
        return false;
    }
};

// 태스크 보드 업데이트 성공 콜백
scwin.update_task_board_submitdone = function (e) {

    try {
        // 대기 중인 카드 이동 정보 확인
        if (!scwin.pendingCardMove) {
            return;
        }

        let moveInfo = scwin.pendingCardMove;

        // DOM 업데이트 실행
        moveInfo.targetDOMElement.appendChild(moveInfo.cardElement);

        // 카드의 data-board-id 업데이트
        moveInfo.cardElement.setAttribute("data-board-id", moveInfo.targetBoardId);
        // allTasksData 로컬 캐시 업데이트
        scwin.updateLocalTaskCache(moveInfo.taskId, moveInfo.targetBoardId);

        // 이동 완료 알림
        let sourceBoard = scwin.getBoardTitle(moveInfo.sourceBoardId);
        let targetBoard = scwin.getBoardTitle(moveInfo.targetBoardId);

        // WebSocket을 통해 다른 사용자에게 알림
        if (scwin.isWebSocketConnected) {
            let projectId = $p.parent().dm_projectVo.get("projectId");
            scwin.sendWebSocketMessage({
                type: "CARD_MOVED",
                taskId: moveInfo.taskId,
                fromBoardId: moveInfo.sourceBoardId,
                toBoardId: moveInfo.targetBoardId,
                projectId: projectId,
                timestamp: Date.now()
            });
        }

        // 대기 정보 초기화
        scwin.pendingCardMove = null;


    } catch (error) {
        // 에러가 발생해도 대기 정보는 초기화
        scwin.pendingCardMove = null;
    }
};

// 태스크 보드 업데이트 실패 콜백
scwin.update_task_board_submiterror = function (e) {

    try {
        // 대기 중인 카드 이동 정보 확인
        if (scwin.pendingCardMove) {
            let moveInfo = scwin.pendingCardMove;

            // 대기 정보 초기화
            scwin.pendingCardMove = null;
        }
    } catch (error) {
    }
};

// 로컬 캐시에서 태스크 정보 업데이트
scwin.updateLocalTaskCache = function (taskId, newBoardId) {
    try {
        if (!scwin.allTasksData) {
            scwin.allTasksData = {};
        }

        let movedTask = null;
        let sourceBoardId = null;

        // 모든 보드의 캐시에서 해당 태스크를 찾아서 제거
        for (let boardId in scwin.allTasksData) {
            if (scwin.allTasksData.hasOwnProperty(boardId)) {
                let tasks = scwin.allTasksData[boardId];
                for (let i = 0; i < tasks.length; i++) {
                    if (tasks[i].taskId === taskId) {
                        movedTask = tasks[i];
                        sourceBoardId = boardId;

                        // 기존 보드에서 제거 (다른 보드로 이동하는 경우에만)
                        if (boardId !== newBoardId) {
                            tasks.splice(i, 1);
                        }
                        break;
                    }
                }
                if (movedTask) break;
            }
        }

        // 태스크를 찾았고 다른 보드로 이동하는 경우
        if (movedTask && sourceBoardId !== newBoardId) {
            // 태스크의 boardId 업데이트
            movedTask.boardId = newBoardId;

            // 새 보드 캐시에 추가
            if (!scwin.allTasksData[newBoardId]) {
                scwin.allTasksData[newBoardId] = [];
            }
            scwin.allTasksData[newBoardId].push(movedTask);

            // 변경된 보드들의 화면 업데이트
            scwin.sortAndFilterBoardTasks(sourceBoardId);
            scwin.sortAndFilterBoardTasks(newBoardId);
        }


    } catch (error) {
    }
};

/**
 * 보드 제목에 따른 상태 색상 반환
 * @param {String} boardTitle - 보드 제목
 * @returns {String} 색상 코드
 */
scwin.getBoardStatusColor = function (boardTitle) {
    // boardTitle null 체크
    if (!boardTitle || typeof boardTitle !== 'string') {
        return '#656d76'; // 기본 회색
    }

    let title = boardTitle.toLowerCase();

    if (title.includes('할 일') || title.includes('todo')) {
        return '#fb8500'; // 주황색
    } else if (title.includes('진행') || title.includes('progress') || title.includes('진행중')) {
        return '#d4af37'; // 금색
    } else if (title.includes('완료') || title.includes('done') || title.includes('완성')) {
        return '#1f883d'; // 녹색
    } else {
        return '#656d76'; // 기본 회색
    }
};

/**
 * 동적 카드 추가 버튼 클릭 핸들러
 */
scwin.dynamicAddCard_onclick_fixed = function (boardId) {

    if (boardId) {
        // 해당 보드의 카드 컨테이너 찾기
        let cardContainerId = "card_container_" + boardId;
        let parentGroup = eval(cardContainerId);

        if (!parentGroup) {
            $c.win.alert("카드 컨테이너를 찾을 수 없습니다.");
            return;
        }


        // 동적 카드와 input 생성
        let cardId = "dyn_card_" + new Date().getTime();
        let cardOptions = {
            className: "project-card",
            style: "border-color: #2da44e; background-color: #f6ffed;"
        };
        let newCard = $p.dynamicCreate(cardId, "group", cardOptions, parentGroup);

        if (newCard) {
            // 동적 input 생성
            let inputId = "dyn_input_" + new Date().getTime();
            let newInput = $p.dynamicCreate(inputId, "input", {
                placeholder: "새 작업명을 입력하세요.",
                style: "width: 100%; height: 24px;"
            }, newCard);

            if (newInput) {
                // boardId를 input의 data 속성에 저장 (WebSquare 호환)
                newInput.setUserData("boardId", boardId);

                // 키보드 이벤트 바인딩 시 boardId를 클로저로 전달
                newInput.bind("onkeydown", function (e) {
                    scwin.dynamicInput_onkeydown_with_board.call(this, e, boardId);
                });

                // input에 포커스
                newInput.focus();

            } else {
                newCard.remove();
            }
        } else {
        }
    }
    else {
    }
};

/**
 * 동적 input 키보드 이벤트 핸들러 (boardId 포함)
 */
scwin.dynamicInput_onkeydown_with_board = function (e, boardId) {
    let inputComponent = this;
    let keyCode = e.keyCode;

    // boardId 가져오기 (파라미터 우선, 없으면 userData에서 가져오기)
    let targetBoardId = boardId || inputComponent.getUserData("boardId");


    if (keyCode === 13) { // Enter 키
        let input = inputComponent.getValue();
        if (input && input.trim()) {

            if (!targetBoardId) {
                $c.win.alert("보드 정보를 찾을 수 없습니다.");
                return;
            }

            // dm_taskVo에 데이터 설정
            dm_taskVo.set("taskTitle", input.trim());
            dm_taskVo.set("boardId", targetBoardId);

            // 태스크 생성 API 호출
            $p.executeSubmission("add_task");

            // input 카드 제거
            let cardComponent = inputComponent.getParent();
            if (cardComponent) {
                cardComponent.remove();
            }
        } else {
            $c.win.alert("작업명을 입력해주세요.");
        }
    } else if (keyCode === 27) { // ESC 키

        // 카드 제거
        let cardComponent = inputComponent.getParent();
        if (cardComponent) {
            cardComponent.remove();
        }
    }
};

/**
 * 보드 로드 서브미션 전 처리 함수
 */
scwin.load_Board_submit = function (e) {

    // 프로젝트 ID 확인
    let projectId = dm_projectVo.get("projectId");
    if (!projectId) {

        // scwin.currentProjectData에서 프로젝트 ID를 찾아보기
        if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
            dm_projectVo.set("projectId", scwin.currentProjectData.projectId);
            projectId = scwin.currentProjectData.projectId;
        } else {
            return false; // 서브미션 중단
        }
    }

    return true; // 서브미션 계속 진행
};

/**
 * 보드 로드 서브미션 에러 처리 함수
 */
scwin.load_Board_submiterror = function (e) {

    let errorMessage = "보드 데이터를 로드하는데 실패했습니다.";

    // 에러 타입별 처리
    if (e.responseJSON && e.responseJSON.message) {
        errorMessage += "\n원인: " + e.responseJSON.message;
    } else if (e.status) {
        errorMessage += "\n상태코드: " + e.status;
        if (e.status === 404) {
            errorMessage += "\n해당 프로젝트의 보드를 찾을 수 없습니다.";
        } else if (e.status === 500) {
            errorMessage += "\n서버 오류가 발생했습니다.";
        }
    }

    $c.win.alert(errorMessage);

    // 에러 시 로그만 출력 (정적 컬럼 제거됨)
};


