//task 버튼 눌렀을 때 
scwin.new_task_onclick = function (e) {
    // 클릭된 카드에서 taskId와 projectId 추출
    let taskId = null;
    let projectId = dm_projectVo.get("projectId");

    if (e && e.target) {
        // 클릭된 요소나 부모 요소에서 data-task-id 찾기
        let currentElement = e.target;
        while (currentElement && !taskId) {
            if (currentElement.getAttribute && currentElement.getAttribute("data-task-id")) {
                taskId = currentElement.getAttribute("data-task-id");
                break;
            }
            currentElement = currentElement.parentElement;
        }
    }

    // 보드 타이틀 가져오기
    let boardTitle = "알 수 없음";
    if (e && e.target) {
        let currentElement = e.target;
        while (currentElement && boardTitle === "알 수 없음") {
            if (currentElement.getAttribute && currentElement.getAttribute("data-board-id")) {
                let boardId = currentElement.getAttribute("data-board-id");
                boardTitle = scwin.getBoardTitle(boardId);
                break;
            }
            currentElement = currentElement.parentElement;
        }
    }

    // 프로젝트 이름 가져오기
    let projectName = "프로젝트";
    if (scwin.currentProjectData && scwin.currentProjectData.projectName) {
        projectName = scwin.currentProjectData.projectName;
    }

    // 팝업 이름 동적 생성
    let popupName = projectName + " / " + boardTitle;


    // 사용자 정보 가져오기 (안전한 방법으로)
    let userId = scwin.getCurrentUserId();
    if (!userId) {
        return;
    }

    let userName = userId; // userId를 userName으로 사용
    let userImage = "/InsWebApp/images/default-avatar.png"; // 기본 아바타 이미지

    let param = {
        "type": "json",
        "name": "userInfo",
        "data": {
            "userId": userId,
            "userName": userName,
            "userImage": userImage,
            "taskId": taskId,
            "projectId": projectId
        }
    };

    // 팝업 생성 옵션 지정
    let options = {
        id: "exa_popup",
        type: "wframePopup",
        width: "1350",
        height: "800",
        top: "115",
        left: "330",
        popupName: popupName,
        modal: false,
        closeAction: "scwin.popup_closeAction",
        customTitleBar: false,
        dataObject: param
    };

    // 팝업 생성
    $p.openPopup("/InsWebApp/ui/project/taskModal.xml", options);

};

