// 화상통화 모달 닫기 함수 (자식 페이지에서 호출용)
scwin.closeVideoChatModal = function (isPipMode) {


    // PIP 모드일 때는 모달만 닫고 화상통화는 유지
    if (isPipMode || scwin.isPipModeActive) {

        scwin.isPipModeActive = true; // PIP 모드 활성화 표시

        // PIP 모드에서는 간단하게 모달만 닫기
        if (scwin.currentVideoChatPopupId) {
            $p.closePopup(scwin.currentVideoChatPopupId);
        } else {
            $p.closePopup("videoChatPopup");
        }
        return; // 화상통화 종료 없이 여기서 끝
    }



    // 방법 1: 동적 ID로 정상적인 closePopup 호출
    if (scwin.currentVideoChatPopupId) {

        $p.closePopup(scwin.currentVideoChatPopupId);
        scwin.currentVideoChatPopupId = null;
    } else {
        // fallback
        $p.closePopup("videoChatPopup");
    }

    // 방법 2: 강제 DOM 제거
    setTimeout(function () {
        try {

            let selectors = [
                '#videoChatPopup',
                '[id*="videoChatPopup"]',
                '[id*="popup"][id*="video"]',
                '[id*="mf_wfr_mainContent_videoChatPopup"]',
                '.w2popup_window',
                '.wframe_popup'
            ];

            selectors.forEach(function (selector) {
                let elements = document.querySelectorAll(selector);
                elements.forEach(function (element) {

                    element.remove();
                });
            });

            // 백드롭 제거
            let backdrop = document.querySelector('.w2popup_backdrop');
            if (backdrop) {
                backdrop.remove();

            }

        } catch (e) {

        }

        // 화상통화 모달이 완전히 닫힌 후 다른 팝업들의 헤더 복원
        setTimeout(function() {
            try {
                // 모든 WebSquare 팝업 헤더를 다시 표시
                let allHeaders = document.querySelectorAll('.w2window_header');
                for (let i = 0; i < allHeaders.length; i++) {
                    let header = allHeaders[i];
                    // 화상통화 팝업이 아닌 헤더들만 복원
                    if (!header.closest('[id*="videoChatPopup"]')) {
                        header.style.display = '';
                        header.style.height = '';
                        header.style.minHeight = '';
                        header.style.visibility = '';
                    }
                }

                // 추가로 WebSquare 기본 헤더 스타일 복원
                let popupHeaders = document.querySelectorAll('.w2popup_window .w2window_header');
                for (let j = 0; j < popupHeaders.length; j++) {
                    let popupHeader = popupHeaders[j];
                    // 화상통화 팝업이 아닌 헤더들만 복원
                    if (!popupHeader.closest('[id*="videoChatPopup"]')) {
                        popupHeader.style.display = '';
                        popupHeader.style.height = '';
                        popupHeader.style.minHeight = '';
                        popupHeader.style.visibility = '';
                    }
                }


            } catch (error) {

            }
        }, 200);

    }, 100);
};

// PIP 상태 저장을 위한 전역 변수
scwin.pipVideoState = null;
scwin.isPipModeActive = false; // PIP 모드 활성화 상태
scwin.originalModalInfo = null; // 원래 모달 크기/위치 저장

// 모달을 PIP 크기로 축소하는 함수
scwin.resizeModalToPip = function () {

    scwin.isPipModeActive = true;

    try {
        // 현재 활성화된 화상통화 모달 찾기
        const modalSelectors = [
            '[id*="videoChatPopup"]',
            '[id*="mf_wfr_mainContent_videoChatPopup"]'
        ];

        let modalElement = null;
        for (const selector of modalSelectors) {
            const elements = document.querySelectorAll(selector);
            for (const element of elements) {
                if (element.style.display !== 'none' && element.offsetWidth > 0) {
                    modalElement = element;
                    break;
                }
            }
            if (modalElement) break;
        }

        if (modalElement) {
            // 원래 크기/위치 저장 (복원용)
            scwin.originalModalInfo = {
                width: modalElement.style.width || modalElement.offsetWidth + 'px',
                height: modalElement.style.height || modalElement.offsetHeight + 'px',
                left: modalElement.style.left || '',
                top: modalElement.style.top || '',
                position: modalElement.style.position || ''
            };

            // PIP 크기/위치로 변경
            modalElement.style.setProperty('width', '320px', 'important');
            modalElement.style.setProperty('height', '240px', 'important');
            modalElement.style.setProperty('position', 'fixed', 'important');
            modalElement.style.setProperty('bottom', '20px', 'important');
            modalElement.style.setProperty('right', '20px', 'important');
            modalElement.style.setProperty('top', 'auto', 'important');
            modalElement.style.setProperty('left', 'auto', 'important');
            modalElement.style.setProperty('z-index', '999999', 'important');



            // PIP 확대 버튼 추가
            scwin.addPipExpandButton(modalElement);

        } else {

        }

    } catch (error) {

    }
};

// PIP 확대 버튼 추가
scwin.addPipExpandButton = function (modalElement) {
    // 기존 확대 버튼이 있으면 제거
    const existingBtn = modalElement.querySelector('.pip-expand-btn');
    if (existingBtn) existingBtn.remove();

    // 확대 버튼 생성
    const expandBtn = document.createElement('button');
    expandBtn.className = 'pip-expand-btn';
    expandBtn.innerHTML = '⛶';
    expandBtn.style.cssText = `
        position: absolute !important;
        top: 5px !important;
        right: 25px !important;
        width: 20px !important;
        height: 20px !important;
        background: #FFB823 !important;
        border: none !important;
        border-radius: 3px !important;
        color: white !important;
        font-size: 12px !important;
        cursor: pointer !important;
        z-index: 1000000 !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
    `;

    // 확대 버튼 클릭 이벤트
    expandBtn.addEventListener('click', function () {
        scwin.expandModalFromPip();
    });

    modalElement.appendChild(expandBtn);

};

// PIP에서 모달 확대 복원
scwin.expandModalFromPip = function () {

    scwin.isPipModeActive = false;

    try {
        // resizeModalToPip와 동일한 방식으로 모달 요소 찾기
        const modalSelectors = [
            '[id*="videoChatPopup"]',
            '[id*="mf_wfr_mainContent_videoChatPopup"]'
        ];

        let modalElement = null;
        for (const selector of modalSelectors) {
            const elements = document.querySelectorAll(selector);
            for (const element of elements) {
                if (element.style.display !== 'none' && element.offsetWidth > 0) {
                    modalElement = element;
                    break;
                }
            }
            if (modalElement) break;
        }

        if (modalElement) {
            // 정확한 원래 크기로 복원 (1920x940)
            modalElement.style.setProperty('width', '1920px', 'important');
            modalElement.style.setProperty('height', '940px', 'important');
            modalElement.style.setProperty('position', 'absolute', 'important');
            modalElement.style.setProperty('left', '0px', 'important');
            modalElement.style.setProperty('top', '0px', 'important');
            modalElement.style.setProperty('bottom', 'auto', 'important');
            modalElement.style.setProperty('right', 'auto', 'important');
            modalElement.style.setProperty('z-index', '999999', 'important');

            // 확대 버튼 제거
            const expandBtn = modalElement.querySelector('.pip-expand-btn');
            if (expandBtn) expandBtn.remove();



            // 자식 창에 복원 알림
            const iframe = modalElement.querySelector('iframe');
            if (iframe && iframe.contentWindow) {
                iframe.contentWindow.postMessage({
                    action: 'restoreFromPip'
                }, '*');
            }

        } else {

        }

    } catch (error) {

    }
};

// PostMessage 이벤트 리스너 추가 (자식 창에서 보낸 메시지 처리)
window.addEventListener('message', function (event) {

    // PIP 창 생성 요청 처리
    if (event.data && event.data.action === 'createPipWindow') {

        scwin.createPipWindow(event.data.videoState);
        return;
    }

    // 화상통화 상태 저장 요청 처리
    if (event.data && event.data.action === 'saveVideoChatState') {

        scwin.pipVideoState = event.data.state;
        return;
    }

    // 모달 PIP 크기 축소 요청 처리
    if (event.data && event.data.action === 'resizeModalToPip') {


        try {
            // 즉시 실행
            scwin.resizeModalToPip();


            // 추가로 짧은 지연 후 한 번 더 실행 (안전장치)
            setTimeout(() => {

                scwin.resizeModalToPip();
            }, 50);

        } catch (error) {

        }
        return;
    }

    // 모달 PIP에서 확대 복원 요청 처리
    if (event.data && event.data.action === 'expandModalFromPip') {


        try {
            scwin.expandModalFromPip();

        } catch (error) {

        }
        return;
    }

    // 화상통화 모달 재열기 요청 처리
    if (event.data && event.data.action === 'reopenVideoChatPopup') {

        scwin.isPipModeActive = false; // PIP 모드 해제
        // 화상통화 버튼 클릭과 동일한 동작 수행
        scwin.btn_videoCall_onclick();
        return;
    }

    if (event.data && event.data.action === 'closeVideoChatPopup') {
        // PIP 모드와 일반 모드 구분 처리
        if (event.data.isPipMode) {

            scwin.isPipModeActive = true; // PIP 모드 활성화

            // PIP 모드에서는 모달만 숨기기 (DOM 제거하지 않음)
            try {


                // 방법 1: 모달 DOM을 숨기기만 함 (제거하지 않음)
                const selectors = [
                    '[id*="videoChatPopup"]',
                    '[id*="mf_wfr_mainContent_videoChatPopup"]'
                ];

                let hiddenCount = 0;
                selectors.forEach(selector => {
                    const elements = document.querySelectorAll(selector);
                    elements.forEach(element => {
                        if (element && element.style) {
                            element.style.setProperty('display', 'none', 'important');
                            hiddenCount++;
                        }
                    });
                });


            } catch (e) {

            }
            return; // 화상통화 종료 없이 여기서 끝
        }



        // 간단하고 안전한 모달 닫기
        try {
            ;

            // 1단계: WebSquare API로 정식 팝업 닫기
            if (typeof $p !== 'undefined' && $p.closePopup) {

                $p.closePopup("videoChatPopup");
            }

            // 2단계: 화상통화 DOM 완전 정리 (ID 중복 오류 방지)


            // 1) videoChatPopup 관련 모든 요소 제거
            let videoSelectors = [
                '[id*="videoChatPopup"]',
                '[id*="mf_wfr_mainContent_videoChatPopup"]',
                '.videochat-popup',
                '.video-chat-container'
            ];

            let totalRemoved = 0;
            videoSelectors.forEach(function (selector) {
                let elements = document.querySelectorAll(selector);
                elements.forEach(function (element) {

                    element.remove();
                    totalRemoved++;
                });
            });

            // 2) WebSquare 내부 캐시도 정리
            try {
                if (typeof $p !== 'undefined' && $p.destroyPopup) {
                    $p.destroyPopup("videoChatPopup");

                } else if (typeof $p !== 'undefined' && $p.removePopup) {
                    $p.removePopup("videoChatPopup");

                }
            } catch (e) {

            }



            // 3단계: 강제 페이지 활성화 (백드롭 대신)
            document.body.style.pointerEvents = 'auto !important';
            document.body.style.filter = 'none !important';
            document.body.style.opacity = '1 !important';
            document.documentElement.style.pointerEvents = 'auto !important';



            // 4단계: 기본 스타일 초기화
            document.body.style.pointerEvents = 'auto';
            document.body.style.overflow = 'auto';



        } catch (e) {

        }
    }
});

