// PIP 창 드래그 기능 구현
scwin.makePipDraggable = function (pipWindow, dragHandle) {
    let isDragging = false;
    let startX, startY, startLeft, startTop;

    dragHandle.addEventListener('mousedown', function (e) {
        isDragging = true;
        startX = e.clientX;
        startY = e.clientY;
        startLeft = parseInt(window.getComputedStyle(pipWindow).left);
        startTop = parseInt(window.getComputedStyle(pipWindow).top);

        document.addEventListener('mousemove', handleDrag);
        document.addEventListener('mouseup', stopDrag);

        e.preventDefault();
    });

    function handleDrag(e) {
        if (!isDragging) return;

        const deltaX = e.clientX - startX;
        const deltaY = e.clientY - startY;

        let newLeft = startLeft + deltaX;
        let newTop = startTop + deltaY;

        // 화면 경계 제한
        const maxLeft = window.innerWidth - pipWindow.offsetWidth;
        const maxTop = window.innerHeight - pipWindow.offsetHeight;

        newLeft = Math.max(0, Math.min(newLeft, maxLeft));
        newTop = Math.max(0, Math.min(newTop, maxTop));

        pipWindow.style.left = newLeft + 'px';
        pipWindow.style.top = newTop + 'px';
        pipWindow.style.right = 'auto';
        pipWindow.style.bottom = 'auto';
    }

    function stopDrag() {
        isDragging = false;
        document.removeEventListener('mousemove', handleDrag);
        document.removeEventListener('mouseup', stopDrag);
    }
};

// PIP 창 리사이즈 기능 구현
scwin.makePipResizable = function (pipWindow, resizeHandle) {
    let isResizing = false;
    let startX, startY, startWidth, startHeight;

    resizeHandle.addEventListener('mousedown', function (e) {
        isResizing = true;
        startX = e.clientX;
        startY = e.clientY;
        startWidth = parseInt(window.getComputedStyle(pipWindow).width);
        startHeight = parseInt(window.getComputedStyle(pipWindow).height);

        document.addEventListener('mousemove', handleResize);
        document.addEventListener('mouseup', stopResize);

        e.preventDefault();
        e.stopPropagation();
    });

    function handleResize(e) {
        if (!isResizing) return;

        const deltaX = e.clientX - startX;
        const deltaY = e.clientY - startY;

        let newWidth = startWidth + deltaX;
        let newHeight = startHeight + deltaY;

        // 최소/최대 크기 제한
        newWidth = Math.max(250, Math.min(newWidth, 600));
        newHeight = Math.max(180, Math.min(newHeight, 400));

        pipWindow.style.width = newWidth + 'px';
        pipWindow.style.height = newHeight + 'px';
    }

    function stopResize() {
        isResizing = false;
        document.removeEventListener('mousemove', handleResize);
        document.removeEventListener('mouseup', stopResize);
    }
};

