            projectId = scwin.pipVideoState.projectId;
        }

        // 대안: currentProjectData에서 가져오기
        if (!projectId && scwin.currentProjectData && scwin.currentProjectData.projectId) {
            projectId = scwin.currentProjectData.projectId;
        }

        // 대안: dm_projectVo에서 가져오기
        if (!projectId) {
            try {
                projectId = dm_projectVo.get("projectId");
            } catch (e) {
            }
        }

        if (!projectId) {
                return;
        }



        // PIP 창 제거
        const pipWindow = document.getElementById('videoChatPipWindow');
        if (pipWindow) {
            pipWindow.remove();
        }

        // 전체 화상통화 모달 다시 열기
        let param = {
            "type": "json",
            "name": "projectInfo",
            "data": {
                "projectId": projectId,
                "fromPip": true  // PIP에서 확장된 것임을 표시
            }
        };

        let options = {
            id: "videoChatPopup",
            type: "wframePopup",
