            closeAction: "scwin.videoChat_closeAction",
            dataObject: param
        };

        // 화상통화 팝업 다시 열기
        $p.openPopup("/InsWebApp/ui/videochat/webRTCVideoChatPage.xml", options);



    } catch (error) {

        $c.win.alert("화상통화를 확장할 수 없습니다: " + error.message);
    }
};

