/**
 * 보드 추가 성공 처리
 */
scwin.add_board_submitdone = function (e) {

    try {
        // 생성 성공 시 임시 보드 제거
        if (scwin.currentTempBoardId) {
            scwin.removeTempBoard(scwin.currentTempBoardId);
            scwin.currentTempBoardId = null;
        }

        // 보드 목록 다시 조회하여 전체 새로고침
        $p.executeSubmission("load_Board");

    } catch (error) {

        // 오류 시 임시 보드 제거
        if (scwin.currentTempBoardId) {
            scwin.removeTempBoard(scwin.currentTempBoardId);
            scwin.currentTempBoardId = null;
        }
    }
};

/**
 * 보드 추가 실패 처리
 */
scwin.add_board_submiterror = function (e) {

    let errorMessage = "보드 생성에 실패했습니다.";

    if (e.responseJSON && e.responseJSON.message) {
        errorMessage += "\n원인: " + e.responseJSON.message;
    } else if (e.status) {
        errorMessage += "\n상태코드: " + e.status;
    }

    $c.win.alert(errorMessage);

    // 실패 시 임시 보드 제거
    if (scwin.currentTempBoardId) {
        scwin.removeTempBoard(scwin.currentTempBoardId);
        scwin.currentTempBoardId = null;
    }
};

