scwin.delete_board_submiterror = function (e) {

    let errorMessage = "보드 삭제에 실패했습니다.";

    // 오류 메시지 상세화
    if (e.responseJSON && e.responseJSON.message) {
        errorMessage += "\n원인: " + e.responseJSON.message;
    } else if (e.responseText) {
        try {
            let errorData = JSON.parse(e.responseText);
            if (errorData.message) {
                errorMessage += "\n원인: " + errorData.message;
            }
        } catch (parseError) {
        }
    } else if (e.status) {
        errorMessage += "\n상태코드: " + e.status;

        // 일반적인 HTTP 상태코드 설명 추가
        if (e.status === 403) {
            errorMessage += "\n권한이 없습니다.";
        } else if (e.status === 404) {
            errorMessage += "\n보드를 찾을 수 없습니다.";
        } else if (e.status === 500) {
            errorMessage += "\n서버 내부 오류입니다.";
        }
    }

    $c.win.alert(errorMessage);
};

/**
 * input 태그가 있는 빈 보드 컬럼 생성
 */
scwin.createEmptyBoardWithInput = function (projectId) {

    try {
        let kanbanContainer = grp_kanban_board;
        if (!kanbanContainer) {
            return;
        }

        // 임시 보드 ID 생성
        let tempBoardId = "temp_board_" + new Date().getTime();
        let columnId = "grp_dynamic_" + tempBoardId;

        // 1. 메인 컬럼 그룹 생성
        let columnGroup = $p.dynamicCreate(
            columnId,
            "group",
            {
                className: "kanban-column",
                style: "flex: 0 0 300px; margin: 0 8px; background: #f6f8fa; border-radius: 8px; padding: 16px;",
                "data-board-id": tempBoardId,
                "data-temp-board": "true"
            },
            kanbanContainer
        );

        if (!columnGroup) {
            return;
        }

        // 2. 컬럼 헤더 생성
        let headerGroup = $p.dynamicCreate(
            columnId + "_header",
            "group",
            {
                className: "kanban-column-header",
                style: "display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px;"
            },
            columnGroup
        );

        // 3. 제목 입력 영역 생성
        let titleGroup = $p.dynamicCreate(
            columnId + "_title_group",
            "group",
            {
                style: "display: flex; align-items: center; gap: 8px; width: 100%;"
            },
            headerGroup
        );

        // 4. 상태 인디케이터 생성
        let statusIndicator = $p.dynamicCreate(
            columnId + "_status",
            "output",
            {
                className: "status-indicator",
                style: "width: 8px; height: 8px; border-radius: 50%; background-color: #999999;"
            },
            titleGroup
        );

        // 5. 보드명 입력 input 생성
        let titleInput = $p.dynamicCreate(
            columnId + "_input",
            "input",
            {
                placeholder: "보드 이름을 입력하세요",
                style: "width: 100%; padding: 6px 8px; border: 1px solid #d1d9e0; border-radius: 4px; font-weight: 600; font-size: 14px; background: white;",
                "data-project-id": projectId,
                "data-temp-board-id": tempBoardId
            },
            titleGroup
        );

        if (titleInput) {
            // input에 키보드 이벤트 바인딩
            titleInput.bind("onkeydown", scwin.boardInput_onkeydown);

            // input에 포커스 주기
            setTimeout(function () {
                titleInput.focus();
            }, 100);
        }

        // 6. 빈 카드 컨테이너 생성
        let cardContainer = $p.dynamicCreate(
            columnId + "_container",
            "group",
            {
                className: "kanban-cards-container",
                style: "display: flex; flex-direction: column; gap: 8px; min-height: 100px; width: 100%; opacity: 0.5;",
                "data-board-id": tempBoardId
            },
            columnGroup
        );

        // 7. 안내 텍스트 추가
        let guideText = $p.dynamicCreate(
            columnId + "_guide",
            "output",
            {
                style: "text-align: center; color: #656d76; font-size: 12px; padding: 20px; font-style: italic;"
            },
            cardContainer
        );

        if (guideText) {
            guideText.setValue("Enter: 보드 생성 | ESC: 취소");
        }


    } catch (error) {
    }
};

/**
 * 보드명 입력 input의 키보드 이벤트 처리
 */
scwin.boardInput_onkeydown = function (e) {
    let inputComponent = this;
    let keyCode = e.keyCode;

    if (keyCode === 13) { // Enter 키 - 보드 생성
        let boardTitle = inputComponent.getValue();

        if (boardTitle && boardTitle.trim() !== "") {
            let projectId = inputComponent.getAttribute("data-project-id");
            let tempBoardId = inputComponent.getAttribute("data-temp-board-id");

            // 임시 보드 ID 저장 (생성 성공 시 교체용)
            scwin.currentTempBoardId = tempBoardId;

            // 데이터 설정
            dm_boardVo_add.set("boardTitle", boardTitle.trim());
            dm_boardVo_add.set("projectId", projectId);

            // 서버에 보드 생성 요청
            $p.executeSubmission("add_board");

        } else {
            $c.win.alert("보드 이름을 입력해주세요.");
            inputComponent.focus();
        }

    } else if (keyCode === 27) { // ESC 키 - 취소

        // 임시 보드 컬럼 제거
        let tempBoardId = inputComponent.getAttribute("data-temp-board-id");
        let columnId = "grp_dynamic_" + tempBoardId;

        try {
            let columnComponent = eval(columnId);
            if (columnComponent) {
                columnComponent.remove();
            }
        } catch (error) {
        }
    }
};

