/**
 * 사용자 이름을 포함한 태스크 목록 로드 성공 콜백
 */
scwin.load_Tasks_With_UserName_submitdone = function (e) {
    if (scwin.individualLoadStartTime) {
        scwin.individualLoadStartTime = null; // 리셋
    }

    // 중복 호출 방지 플래그 리셋
    scwin.isTaskListWithUserNameLoading = false;

    // 1. 응답에서 직접 태스크 목록 추출
    let responseData = e.responseJSON;

    // 새로운 태스크만 처리 (누적하지 않음)
    let newTasks = responseData.elData.taskVoList || [];

    // scwin.taskList에 태스크 데이터 할당 (간트차트 데이터 동기화용)
    if (!scwin.taskList) {
        scwin.taskList = [];
    }
    scwin.taskList = scwin.taskList.concat(newTasks);

    // 칸반 보드용 태스크 처리 (보드별로 분리 저장)
    if (newTasks && newTasks.length > 0) {
        // 보드별로 태스크 데이터 분리
        let tasksByBoard = {};
        for (let i = 0; i < newTasks.length; i++) {
            let task = newTasks[i];
            if (!tasksByBoard[task.boardId]) {
                tasksByBoard[task.boardId] = [];
            }
            tasksByBoard[task.boardId].push(task);
        }

        // 각 보드별로 데이터 저장 및 표시
        for (let boardId in tasksByBoard) {
            let boardTasks = tasksByBoard[boardId];

            // 서버에서 받은 데이터 정렬 상태 확인
            for (let i = 0; i < Math.min(boardTasks.length, 5); i++) {
                let task = boardTasks[i];
            }
            if (boardTasks.length > 5) {
            }

            // 전체 태스크 데이터를 로컬에 저장
            scwin.storeAllTasksData(boardId, boardTasks);

            // 필터링과 정렬을 모두 적용하여 태스크 표시
            scwin.sortAndFilterBoardTasks(boardId);

            // 정렬 요청 완료 추적
            if (typeof scwin.sortRequestCount === 'number') {
                scwin.sortRequestCount++;
                if (scwin.sortRequestCount >= scwin.expectedSortRequests) {
                }
            }
        }

    } else {

        // boardId 추출 (검색 조건에서)
        let searchCondition = $p.getComponentById("dm_search_task");
        if (searchCondition) {
            let boardId = searchCondition.get("boardId");
            if (boardId) {
                // 빈 데이터 저장 및 정렬/필터링 적용
                scwin.storeAllTasksData(boardId, []);
                scwin.sortAndFilterBoardTasks(boardId);
            }
        }
    }

    // 칸반 데이터 업데이트 후 간트차트 동기화
    scwin.syncGanttWithKanban();
};

/**
 * 사용자 이름을 포함한 태스크 목록 로드 실패 콜백
 */
scwin.load_Tasks_With_UserName_submiterror = function (e) {

    // 중복 호출 방지 플래그 리셋 (중요: 실패 시에도 반드시 리셋)
    scwin.isTaskListWithUserNameLoading = false;

    // 오류 메시지 추출
    let errorMessage = "태스크 목록을 로드하는데 실패했습니다.";
    if (e && e.responseJSON && e.responseJSON.message) {
        errorMessage = e.responseJSON.message;
    } else if (e && e.message) {
        errorMessage = e.message;
    }

    // 쓰레드 제한 오류인 경우 특별 처리
    if (errorMessage.includes("threads") || errorMessage.includes("쓰레드") || errorMessage.includes("thread")) {

        // 3초 후 자동 재시도 (옵션)
        setTimeout(function() {
            if (!scwin.isTaskListWithUserNameLoading) {
                scwin.loadTasksWithUserName();
            }
        }, 3000);
    }

};

// TaskListWithUserName 중복 호출 방지를 위한 전역 상태 관리
scwin.isTaskListWithUserNameLoading = false;
scwin.pendingTaskListRequests = [];

/**
 * 여러 보드의 태스크를 한 번에 로드 (성능 최적화)
 */
scwin.loadAllBoardTasks = function(boardIds) {
    if (scwin.isTaskListWithUserNameLoading) {
        return;
    }

    try {
        scwin.isTaskListWithUserNameLoading = true;

        // 배치 검색 조건 설정 (안전한 접근 방식)
        if (typeof dm_search_task_batch !== 'undefined') {
            dm_search_task_batch.set("boardIds", boardIds.join(","));
            dm_search_task_batch.set("sortField", scwin.currentSortField);
            dm_search_task_batch.set("sortOrder", scwin.currentSortOrder);
        } else {
            let batchSearchCondition = $p.getComponentById("dm_search_task_batch");
            if (batchSearchCondition) {
                batchSearchCondition.set("boardIds", boardIds.join(","));
                batchSearchCondition.set("sortField", scwin.currentSortField);
                batchSearchCondition.set("sortOrder", scwin.currentSortOrder);
            } else {
                throw new Error("dm_search_task_batch 컴포넌트를 찾을 수 없습니다.");
            }
        }

        // 배치 요청 실행
        $p.executeSubmission("load_Tasks_With_UserName_Batch");

    } catch (error) {
        scwin.isTaskListWithUserNameLoading = false;
    }
};

/**
 * 배치 태스크 로드 성공 콜백
 */
scwin.load_Tasks_With_UserName_Batch_submitdone = function (e) {

    // 중복 호출 방지 플래그 리셋
    scwin.isTaskListWithUserNameLoading = false;

    // 1. 응답에서 직접 태스크 목록 추출
    let responseData = e.responseJSON;
    let allTasks = responseData.elData.taskVoList || [];

    // scwin.taskList에 태스크 데이터 할당 (간트차트 데이터 동기화용)
    scwin.taskList = allTasks;

    // 2. 보드별로 태스크 데이터 분리
    let tasksByBoard = {};
    for (let i = 0; i < allTasks.length; i++) {
        let task = allTasks[i];
        if (!tasksByBoard[task.boardId]) {
            tasksByBoard[task.boardId] = [];
        }
        tasksByBoard[task.boardId].push(task);
    }


    // 3. 각 보드별로 데이터 저장 및 표시
    for (let boardId in tasksByBoard) {
        let boardTasks = tasksByBoard[boardId];

        // 전체 태스크 데이터를 로컬에 저장 (필터링용)
        scwin.storeAllTasksData(boardId, boardTasks);

        // 필터링과 정렬을 모두 적용하여 태스크 표시
        scwin.sortAndFilterBoardTasks(boardId);
    }


    // 칸반 데이터 업데이트 후 간트차트 동기화
    scwin.syncGanttWithKanban();
};

/**
 * 배치 태스크 로드 실패 콜백
 */
scwin.load_Tasks_With_UserName_Batch_submiterror = function (e) {

    // 중복 호출 방지 플래그 리셋 (중요: 실패 시에도 반드시 리셋)
    scwin.isTaskListWithUserNameLoading = false;

    // 오류 메시지 추출
    let errorMessage = "배치 태스크 목록을 로드하는데 실패했습니다.";
    if (e && e.responseJSON && e.responseJSON.message) {
        errorMessage = e.responseJSON.message;
    } else if (e && e.message) {
        errorMessage = e.message;
    }

};

/**
 * 사용자 이름 포함 태스크 로드 테스트 함수 (중복 호출 방지 적용)
 */
scwin.loadTasksWithUserName = function () {
    // 중복 호출 방지
    if (scwin.isTaskListWithUserNameLoading) {
        scwin.individualLoadStartTime = null; // 리셋
        return;
    }

    try {
        scwin.isTaskListWithUserNameLoading = true;
        $p.executeSubmission("load_Tasks_With_UserName");
    } catch (error) {
        scwin.isTaskListWithUserNameLoading = false;
        scwin.individualLoadStartTime = null; // 리셋
    }
};

/**
 * 사용자 이름 포함 태스크 로드 비동기 함수 (Promise 반환)
 */
scwin.loadTasksWithUserNameAsync = function () {
    return new Promise((resolve, reject) => {
        try {
            // 기존 콜백 저장
            const originalCallback = scwin.load_Tasks_With_UserName_submitdone;
            const originalErrorCallback = scwin.load_Tasks_With_UserName_submiterror;

            // 임시 콜백 설정
            scwin.load_Tasks_With_UserName_submitdone = function (res) {
                // 원래 콜백 실행
                if (originalCallback && typeof originalCallback === 'function') {
                    originalCallback.call(this, res);
                }
                // 콜백 복원
                scwin.load_Tasks_With_UserName_submitdone = originalCallback;
                scwin.load_Tasks_With_UserName_submiterror = originalErrorCallback;
                // Promise 해결
                resolve(res);
            };

            scwin.load_Tasks_With_UserName_submiterror = function (error) {
                // 원래 에러 콜백 실행
                if (originalErrorCallback && typeof originalErrorCallback === 'function') {
                    originalErrorCallback.call(this, error);
                }
                // 콜백 복원
                scwin.load_Tasks_With_UserName_submitdone = originalCallback;
                scwin.load_Tasks_With_UserName_submiterror = originalErrorCallback;
                // Promise 거부
                reject(error);
            };

            $p.executeSubmission("load_Tasks_With_UserName");
        } catch (error) {
            reject(error);
        }
    });
};

/**
 * 특정 보드의 데이터를 새로고침 (taskModal 저장/삭제 후 호출)
 */
scwin.refreshBoardData = function (boardId) {

  try {
    // 1. 해당 보드의 로컬 캐시 데이터 초기화
    if (scwin.allTasksData && scwin.allTasksData[boardId]) {
      delete scwin.allTasksData[boardId];
    }

    // 2. 서버에서 최신 데이터 다시 로드 (중복 호출 방지 적용)
    if (scwin.isTaskListWithUserNameLoading) {
        return;
    }

    // 검색 조건 설정 (안전한 접근 방식)
    if (typeof dm_search_task !== 'undefined') {
        dm_search_task.set("boardId", boardId);
        dm_search_task.set("sortField", scwin.currentSortField);
        dm_search_task.set("sortOrder", scwin.currentSortOrder);
    } 

    // 3. 태스크 목록 다시 로드
    scwin.isTaskListWithUserNameLoading = true;
    $p.executeSubmission("load_Tasks_With_UserName");

  } catch (error) {
  }
};
